INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_rules_general', 'Battleground Basics', 'Battlegrounds are instanced PvP matches queued for from any Battlemaster NPC or the Battleground UI; most use standard 10-level brackets, though Alterac Valley opens at level 51 and Eye of the Storm, Strand of the Ancients, and Isle of Conquest all require at least level 61-71. Winning awards a burst of Honor plus a Mark of Honor for that battleground, spent at PvP quartermasters on battleground-specific gear, while losing still pays a smaller Honor reward. Patch 3.3.3 added the Random Battleground queue, replacing the old daily battleground quests with a bonus of Honor and Arena Points for the day''s first win; the featured ''Call to Arms'' battleground of the day pays that same bonus for queuing it directly instead of random.', 'battlegrounds,battlemaster,marks of honor,random battleground,call to arms,pvp brackets,random bg', 'pvp,battlegrounds,mechanic');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_warsong_gulch', 'Warsong Gulch', 'Warsong Gulch is a capture-the-flag battleground fought 10-a-side between Horde and Alliance camps in a fenced-off stretch of Ashenvale forest. The first team to carry the enemy''s flag back to their own flag room three times wins the match; a dropped flag resets after a short time if nobody picks it up. It is the lowest-level battleground, open to characters starting at level 10, and is often a new player''s first taste of organized PvP.', 'warsong gulch,wsg,capture the flag,flag room,ashenvale', 'pvp,battlegrounds,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_arathi_basin', 'Arathi Basin', 'Arathi Basin is a resource-control battleground played 15-a-side over five capturable nodes -- the Blacksmith, Farm, Gold Mine, Lumber Mill, and Stables -- scattered across a stretch of the Arathi Highlands. Holding a node generates resources for your team every few seconds, so controlling more nodes at once matters more than any single capture. The first team to reach 2000 resources wins, or whichever team is ahead if the match runs its full length. It opens to characters at level 20.', 'arathi basin,ab,blacksmith,gold mine,lumber mill,stables', 'pvp,battlegrounds,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_alterac_valley', 'Alterac Valley', 'Alterac Valley is the largest battleground, fought up to 40-a-side across the long mountain valley connecting the Horde''s Frostwolf Keep to the Alliance''s Dun Baldar. Each side wins by pushing all the way to the enemy base and killing its final boss -- Alliance players kill Drek''Thar, Horde players kill Vanndar Stormpike -- while capturing towers and graveyards along the way weakens the enemy''s reinforcements. Its original Vanilla form could run for hours and required razing every enemy tower, bunker, and field commander first; a later redesign cut that down to a much faster rush on the boss, so a 3.3.5a match usually finishes in well under 20 minutes. It opens to characters at level 51, the highest minimum of any standard battleground.', 'alterac valley,av,drek''thar,vanndar stormpike,frostwolf keep,dun baldar', 'pvp,battlegrounds,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_eye_of_the_storm', 'Eye of the Storm', 'Eye of the Storm is a 15-a-side battleground on a floating island in Netherstorm that blends flag-carrying with resource-node control. Teams fight over four capturable towers -- the Blood Elf Tower, Draenei Ruins, Mage Tower, and Fel Reaver Ruins -- that each generate points over time, and picking up the flag at the center of the map and holding it while your team controls nodes adds a large points bonus. The first team to 1600 points wins, or whichever team is ahead when the match''s timer expires. It was added in the Burning Crusade and opens to characters at level 61.', 'eye of the storm,eots,netherstorm,blood elf tower,draenei ruins,mage tower,fel reaver', 'pvp,battlegrounds,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_strand_of_the_ancients', 'Strand of the Ancients', 'Strand of the Ancients is a 15-a-side attack-and-defend battleground off the southern coast of Northrend''s Dragonblight. The attacking team pilots siege engines and demolishers to smash through three walls of gates -- planting seaforium charges or ramming them down -- while defenders man turrets and cannons to hold them off, all racing a countdown clock that resets when a gate falls. If the attackers breach the final gate and detonate the relic at the citadel''s core, the two teams swap roles for a second round, and whichever side broke through faster wins; a team that never breaches loses outright. It shipped with Wrath of the Lich King at launch and opens to characters at level 71.', 'strand of the ancients,sota,siege engine,demolisher,seaforium,relic,dragonblight', 'pvp,battlegrounds,endgame,vehicles');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_isle_of_conquest', 'Isle of Conquest', 'Isle of Conquest is a 40-a-side siege battleground on a Northrend island, added in patch 3.2. Both teams start by fighting over the Docks, Hangar, and Workshop, which unlock siege vehicles and an airship drop onto the enemy keep, while the Refinery and Quarry generate resources that fund reinforcements and boost siege damage. A team wins by breaching the enemy keep and killing its general -- Overlord Agmar for the Horde, Justicar Mariel Trueheart for the Alliance -- or by grinding the other side''s reinforcement count to zero first. Alongside Strand of the Ancients, it is one of the two Wrath-era battlegrounds built around vehicle combat, and it opens to characters at level 71.', 'isle of conquest,ioc,overlord agmar,justicar mariel trueheart,siege vehicles,reinforcements,workshop,hangar', 'pvp,battlegrounds,endgame,vehicles');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ingvar_the_plunderer', 'Ingvar the Plunderer', 'Ingvar the Plunderer is the final boss of Utgarde Keep, a level 69 to 72 five-player dungeon in Howling Fjord. He is resurrected once by a val''kyr after the first kill, so the fight is effectively two rounds.', 'ingvar the plunderer,utgarde keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_keleseth', 'Prince Keleseth', 'Prince Keleseth is the first boss of Utgarde Keep, a level 69 to 72 five-player dungeon in Howling Fjord. He freezes a player in an ice tomb that the rest of the group has to break.', 'prince keleseth,utgarde keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_keristrasza', 'Keristrasza', 'Keristrasza is the final boss of The Nexus, a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. She applies a stacking chill that forces the group to keep moving for the whole fight.', 'keristrasza,the nexus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_grand_magus_telestra', 'Grand Magus Telestra', 'Grand Magus Telestra is a boss of The Nexus, a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. She splits into three copies partway through, each with a different school of magic.', 'grand magus telestra,the nexus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_anub_arak', 'Anub''arak', 'Anub''arak is the final boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. He is the last nerubian king, raised by the Scourge; he also appears as the final encounter of Trial of the Crusader.', 'anub''arak,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_hadronox', 'Hadronox', 'Hadronox is the second boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. The fight is a fighting retreat up a web tunnel while she drags the party''s own pursuers into it.', 'hadronox,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_krik_thir_the_gatewatcher', 'Krik''thir the Gatewatcher', 'Krik''thir the Gatewatcher is the first boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. He is guarded by three named watchers that can be pulled with him.', 'krik''thir the gatewatcher,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_herald_volazj', 'Herald Volazj', 'Herald Volazj is the final boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He casts an insanity effect that puts each player in a private phase fighting shadow copies of the group.', 'herald volazj,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_taldaram', 'Prince Taldaram', 'Prince Taldaram is a boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He is a san''layn vampire who vanishes and embraces a player for heavy damage until two nearby orbs are clicked.', 'prince taldaram,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_elder_nadox', 'Elder Nadox', 'Elder Nadox is the first boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He summons swarms of adds, and one guardian must be killed fast or he becomes immune.', 'elder nadox,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_dred', 'King Dred', 'King Dred is the final boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. He is a devilsaur kept by the Drakkari, and the raptors around him can be pulled in with the fight.', 'king dred,drak''tharon keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_novos_the_summoner', 'Novos the Summoner', 'Novos the Summoner is the second boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. He is untouchable until four channelling crystals around the platform are destroyed.', 'novos the summoner,drak''tharon keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_cyanigosa', 'Cyanigosa', 'Cyanigosa is the final boss of Violet Hold, a level 75 to 77 five-player dungeon in Dalaran. She arrives after the timed prison waves are survived, and is always the last encounter regardless of which mini-bosses spawned.', 'cyanigosa,violet hold', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_gal_darah', 'Gal''darah', 'Gal''darah is the final boss of Gundrak, a level 76 to 78 five-player dungeon in Zul''Drak. He shifts between troll and rhino form, impaling players in one and goring in the other.', 'gal''darah,gundrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_moorabi', 'Moorabi', 'Moorabi is a boss of Gundrak, a level 76 to 78 five-player dungeon in Zul''Drak. He tries to transform into a mammoth, which has to be interrupted or the fight gets much harder.', 'moorabi,gundrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sjonnir_the_ironshaper', 'Sjonnir The Ironshaper', 'Sjonnir The Ironshaper is the final boss of Halls of Stone, a level 77 to 79 five-player dungeon in The Storm Peaks. He is reached after the Tribunal of Ages escort, and floods the room with iron and earthen adds.', 'sjonnir the ironshaper,halls of stone', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_maiden_of_grief', 'Maiden of Grief', 'Maiden of Grief is a boss of Halls of Stone, a level 77 to 79 five-player dungeon in The Storm Peaks. She drops shadow pools that have to be moved out of quickly.', 'maiden of grief,halls of stone', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_loken', 'Loken', 'Loken is the final boss of Halls of Lightning, a level 79 to 80 five-player dungeon in The Storm Peaks. The fight is a damage race against Lightning Nova and a pulse that hits harder the further away you stand.', 'loken,halls of lightning', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_bjarngrim', 'General Bjarngrim', 'General Bjarngrim is the first boss of Halls of Lightning, a level 79 to 80 five-player dungeon in The Storm Peaks. He patrols with an escort and cycles through three combat stances.', 'general bjarngrim,halls of lightning', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_ymiron', 'King Ymiron', 'King Ymiron is the final boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. He is the vrykul king, and he channels power from the burial barrows around the room.', 'king ymiron,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_skadi_the_ruthless', 'Skadi the Ruthless', 'Skadi the Ruthless is a boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. The first half is fought from a drake, throwing harpoons at his mount before he lands.', 'skadi the ruthless,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_svala_sorrowgrave', 'Svala Sorrowgrave', 'Svala Sorrowgrave is the first boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. She sacrifices a player on an altar partway through and must be interrupted or healed past it.', 'svala sorrowgrave,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ley_guardian_eregos', 'Ley-Guardian Eregos', 'Ley-Guardian Eregos is the final boss of The Oculus, a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. He is fought entirely from drake mounts, which is why the dungeon has the reputation it does.', 'ley-guardian eregos,the oculus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mal_ganis', 'Mal''Ganis', 'Mal''Ganis is the final boss of The Culling of Stratholme, a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. He is the dreadlord who baits Arthas into the purge, and he escapes rather than dying.', 'mal''ganis,the culling of stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_chrono_lord_epoch', 'Chrono-Lord Epoch', 'Chrono-Lord Epoch is a boss of The Culling of Stratholme, a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. He is an infinite dragonflight agent trying to stop the purge from happening as it should.', 'chrono-lord epoch,the culling of stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_the_black_knight', 'The Black Knight', 'The Black Knight is the final boss of Trial of the Champion, a level 79 to 80 five-player dungeon in the Argent Tournament grounds in Icecrown. He rises twice after being killed, first as a skeleton and then as a ghost.', 'the black knight,trial of the champion', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_devourer_of_souls', 'Devourer of Souls', 'Devourer of Souls is the final boss of The Forge of Souls, a level 79 to 80 five-player dungeon in Icecrown Citadel. It is a three-faced construct that alternates a mirrored fear with a wailing beam.', 'devourer of souls,the forge of souls', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_bronjahm', 'Bronjahm', 'Bronjahm is the first boss of The Forge of Souls, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is the Godfather of Souls, and at thirty percent health he stops and channels while soul fragments close on him.', 'bronjahm,the forge of souls', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_scourgelord_tyrannus', 'Scourgelord Tyrannus', 'Scourgelord Tyrannus is the final boss of Pit of Saron, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is fought at the end of the scripted escape, after his frost wyrm Rimefang harries the group up the ramp.', 'scourgelord tyrannus,pit of saron', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_forgemaster_garfrost', 'Forgemaster Garfrost', 'Forgemaster Garfrost is the first boss of Pit of Saron, a level 79 to 80 five-player dungeon in Icecrown Citadel. He forges a weapon mid-fight, changing his abilities each time he picks a new one up.', 'forgemaster garfrost,pit of saron', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_falric', 'Falric', 'Falric is the first boss of Halls of Reflection, a level 79 to 80 five-player dungeon in Icecrown Citadel. He appears after a set of scripted waves, and applies a stacking fear that grows through the fight.', 'falric,halls of reflection', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_marwyn', 'Marwyn', 'Marwyn is the second boss of Halls of Reflection, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is the second of the two captains fought before the Lich King chase begins.', 'marwyn,halls of reflection', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kel_thuzad', 'Kel''Thuzad', 'Kel''Thuzad is the final boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is the lich who founded the Scourge''s Cult of the Damned, fought at the top of the necropolis after Sapphiron.', 'kel''thuzad,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sapphiron', 'Sapphiron', 'Sapphiron is the boss before Kel''Thuzad of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. A frost wyrm fought in an ice-covered room where players hide behind ice blocks to survive its breath.', 'sapphiron,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_patchwerk', 'Patchwerk', 'Patchwerk is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. A pure damage-and-healing check with no mechanics to speak of, long used as a benchmark fight.', 'patchwerk,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_thaddius', 'Thaddius', 'Thaddius is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Players are given positive or negative charges and have to split by sign or take heavy raid damage.', 'thaddius,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_heigan_the_unclean', 'Heigan the Unclean', 'Heigan the Unclean is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Known for its dance: the floor erupts in a repeating pattern the whole raid has to keep ahead of.', 'heigan the unclean,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_loatheb', 'Loatheb', 'Loatheb is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Healing is blocked except in brief windows, so healers rotate through a fixed order.', 'loatheb,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_instructor_razuvious', 'Instructor Razuvious', 'Instructor Razuvious is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is tanked by mind-controlled understudies rather than by a player.', 'instructor razuvious,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_maexxna', 'Maexxna', 'Maexxna is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. She webs players to the wall, and the rest of the raid has to free them.', 'maexxna,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_anub_rekhan', 'Anub''Rekhan', 'Anub''Rekhan is the first boss of the Arachnid Quarter of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is a nerubian crypt lord who summons corpse scarabs while chasing a random player.', 'anub''rekhan,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sartharion', 'Sartharion', 'Sartharion is the final boss of The Obsidian Sanctum, a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. Leaving his three drakes alive when he is pulled raises the difficulty and the reward.', 'sartharion,the obsidian sanctum', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_malygos', 'Malygos', 'Malygos is the final boss of The Eye of Eternity, a level 80 ten- and twenty-five-player raid in Coldarra, in the Borean Tundra. The Aspect of Magic, and the fight ends with the whole raid on drakes in a vehicle phase.', 'malygos,the eye of eternity', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_yogg_saron', 'Yogg-Saron', 'Yogg-Saron is the final boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. An Old God fought in three phases, including a stretch inside visions of the past; leaving fewer of Sara''s keepers active makes it much harder.', 'yogg-saron,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_flame_leviathan', 'Flame Leviathan', 'Flame Leviathan is the first boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. The entire fight is fought from siege vehicles rather than on foot.', 'flame leviathan,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mimiron', 'Mimiron', 'Mimiron is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A four-phase mechanical fight, and its hard mode sets the room on fire for the duration.', 'mimiron,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_thorim', 'Thorim', 'Thorim is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. The raid splits in two, one group through an arena gauntlet and one up a corridor, meeting at the top.', 'thorim,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_freya', 'Freya', 'Freya is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Her hard mode is set by leaving up to three elders alive when she is pulled.', 'freya,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kologarn', 'Kologarn', 'Kologarn is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A giant built into the wall, whose two arms are killed separately and regrow.', 'kologarn,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_xt_002_deconstructor', 'XT-002 Deconstructor', 'XT-002 Deconstructor is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Its heart is exposed periodically, and attacking it there is what triggers the hard mode.', 'xt-002 deconstructor,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_algalon_the_observer', 'Algalon the Observer', 'Algalon the Observer is a bonus boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A limited-attempt encounter behind a hard-mode gate, added as the expansion''s most exclusive kill at the time.', 'algalon the observer,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_vezax', 'General Vezax', 'General Vezax is the boss before Yogg-Saron of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Mana regeneration is shut off for the fight, so casters draw from saronite vapours instead.', 'general vezax,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lord_jaraxxus', 'Lord Jaraxxus', 'Lord Jaraxxus is a boss of Trial of the Crusader, a level 80 ten- and twenty-five-player raid in the Argent Tournament grounds in Icecrown. An eredar lord accidentally summoned into the arena partway through the event.', 'lord jaraxxus,trial of the crusader', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_the_lich_king', 'The Lich King', 'The Lich King is the final boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. Arthas Menethil, fought on the roof of the Frozen Throne; it is the last encounter of Wrath of the Lich King. He also appears unkillable at the end of Halls of Reflection.', 'the lich king,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sindragosa', 'Sindragosa', 'Sindragosa is the boss before the Lich King of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. Sapphiron''s risen mate, who stacks a frost debuff that forces players to hide behind ice tombs.', 'sindragosa,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_professor_putricide', 'Professor Putricide', 'Professor Putricide is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. The end of the plague wing, fought around slime pools he brews mid-fight.', 'professor putricide,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lord_marrowgar', 'Lord Marrowgar', 'Lord Marrowgar is the first boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. He impales players on bone spikes and whirlwinds across the room.', 'lord marrowgar,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_deathbringer_saurfang', 'Deathbringer Saurfang', 'Deathbringer Saurfang is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. He gains power from blood drawn off the raid, so damage taken is what fuels him.', 'deathbringer saurfang,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lady_deathwhisper', 'Lady Deathwhisper', 'Lady Deathwhisper is the second boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. She is shielded by mana until it is burned through, and raises adds from the cultists around her.', 'lady deathwhisper,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_blood_queen_lana_thel', 'Blood-Queen Lana''thel', 'Blood-Queen Lana''thel is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. She bites a player who must pass the bite on before a timer, spreading it through the raid.', 'blood-queen lana''thel,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_halion', 'Halion', 'Halion is the final boss of The Ruby Sanctum, a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. He is fought in a physical and a shadow version of the same room at once, with the raid split between them.', 'halion,the ruby sanctum', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archavon_the_stone_watcher', 'Archavon the Stone Watcher', 'Archavon the Stone Watcher is the first boss of Vault of Archavon, a level 80 ten- and twenty-five-player raid in Wintergrasp. He is only reachable by the faction that currently holds Wintergrasp.', 'archavon the stone watcher,vault of archavon', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_onyxia', 'Onyxia', 'Onyxia is the only boss of Onyxia''s Lair, a level 80 ten- and twenty-five-player raid in Dustwallow Marsh. A black dragon fought in ground and air phases; retuned from level 60 to level 80 in patch 3.2.2.', 'onyxia,onyxia''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ragnaros', 'Ragnaros', 'Ragnaros is the final boss of Molten Core, a level 60 to 63 forty-player raid in Blackrock Mountain. A firelord summoned by the Dark Iron dwarves, and the game''s first raid-ending boss.', 'ragnaros,molten core', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_nefarian', 'Nefarian', 'Nefarian is the final boss of Blackwing Lair, a level 60 to 63 forty-player raid in Blackrock Mountain. Deathwing''s son, who calls out class-wide effects by name during the fight.', 'nefarian,blackwing lair', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_hakkar', 'Hakkar', 'Hakkar is the final boss of Zul''Gurub, a level 57 to 63 twenty-player raid in Stranglethorn Vale. The blood god of the Gurubashi trolls, weakened by killing his high priests first.', 'hakkar,zul''gurub', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_c_thun', 'C''Thun', 'C''Thun is the final boss of Ahn''Qiraj Temple, a level 60 to 63 forty-player raid in Silithus. An Old God fought partly from inside its own stomach.', 'c''thun,ahn''qiraj temple', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_edwin_vancleef', 'Edwin VanCleef', 'Edwin VanCleef is the final boss of Deadmines, a level 17 to 20 five-player dungeon in Westfall. The leader of the Defias Brotherhood, fought on the deck of a ship inside the mine.', 'edwin vancleef,deadmines', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archmage_arugal', 'Archmage Arugal', 'Archmage Arugal is the final boss of Shadowfang Keep, a level 18 to 21 five-player dungeon in Silverpine Forest. The renegade mage who created the worgen infesting the keep.', 'archmage arugal,shadowfang keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_baron_rivendare', 'Baron Rivendare', 'Baron Rivendare is the final boss of the undead side of Stratholme, a level 58 to 60 five-player dungeon in the Eastern Plaguelands. He drops the Deathcharger''s Reins, and a timed run of his wing rewards extra loot.', 'baron rivendare,stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_darkmaster_gandling', 'Darkmaster Gandling', 'Darkmaster Gandling is the final boss of Scholomance, a level 58 to 60 five-player dungeon in the Western Plaguelands. The headmaster of the necromancy school, who teleports players into side rooms during the fight.', 'darkmaster gandling,scholomance', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_emperor_dagran_thaurissan', 'Emperor Dagran Thaurissan', 'Emperor Dagran Thaurissan is the final boss of Blackrock Depths, a level 49 to 56 five-player dungeon in Blackrock Mountain. The Dark Iron emperor, fought beside his wife Moira, who must be left alive.', 'emperor dagran thaurissan,blackrock depths', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_illidan_stormrage', 'Illidan Stormrage', 'Illidan Stormrage is the final boss of Black Temple, a level 70 twenty-five-player raid in Shadowmoon Valley. The Betrayer, and the intended final boss of the Burning Crusade before the Sunwell was added.', 'illidan stormrage,black temple', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kael_thas_sunstrider', 'Kael''thas Sunstrider', 'Kael''thas Sunstrider is the final boss of Tempest Keep, a level 70 twenty-five-player raid in Netherstorm. The blood elf prince, fought in a long multi-phase encounter; a weakened version of him is also the final boss of Magister''s Terrace.', 'kael''thas sunstrider,tempest keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lady_vashj', 'Lady Vashj', 'Lady Vashj is the final boss of Coilfang: Serpentshrine Cavern, a level 70 twenty-five-player raid in Zangarmarsh. A naga sea witch whose middle phase requires relaying tainted cores to break her shield.', 'lady vashj,coilfang: serpentshrine cavern', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kil_jaeden', 'Kil''jaeden', 'Kil''jaeden is the final boss of The Sunwell, a level 70 twenty-five-player raid in the Isle of Quel''Danas. The Burning Legion''s second-in-command, and the last boss of the Burning Crusade.', 'kil''jaeden,the sunwell', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archimonde', 'Archimonde', 'Archimonde is the final boss of The Battle for Mount Hyjal, a level 70 twenty-five-player raid in the Caverns of Time in Tanaris. Fought at the World Tree, where players use tears of the goddess to survive his air burst.', 'archimonde,the battle for mount hyjal', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_malchezaar', 'Prince Malchezaar', 'Prince Malchezaar is the final boss of Karazhan, a level 70 to 73 ten-player raid in Deadwind Pass. A eredar prince at the top of the tower, who rains infernals into the room.', 'prince malchezaar,karazhan', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_gruul_the_dragonkiller', 'Gruul the Dragonkiller', 'Gruul the Dragonkiller is the final boss of Gruul''s Lair, a level 70 twenty-five-player raid in Blade''s Edge Mountains. He grows larger and hits harder on a timer, so the raid spreads out to avoid shatter damage.', 'gruul the dragonkiller,gruul''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_magtheridon', 'Magtheridon', 'Magtheridon is the only boss of Magtheridon''s Lair, a level 70 twenty-five-player raid in Hellfire Peninsula. A pit lord held in place by five channelers who must be killed together.', 'magtheridon,magtheridon''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_zul_jin', 'Zul''jin', 'Zul''jin is the final boss of Zul''Aman, a level 70 to 73 ten-player raid in the Ghostlands. The Amani warlord, who cycles through animal-god forms as his health drops.', 'zul''jin,zul''aman', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mekgineer_thermaplugg', 'Mekgineer Thermaplugg', 'Mekgineer Thermaplugg is the final boss of Gnomeregan, a level 25 to 28 five-player dungeon in Dun Morogh. He is fought around a room of bomb-dispensing panels that have to be closed.', 'mekgineer thermaplugg,gnomeregan', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archaedas', 'Archaedas', 'Archaedas is the final boss of Uldaman, a level 37 to 40 five-player dungeon in the Badlands. A titan construct who animates the statues lining the room as adds.', 'archaedas,uldaman', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_murmur', 'Murmur', 'Murmur is the final boss of Auchindoun: Shadow Labyrinth, a level 69 to 70 five-player dungeon in Terokkar Forest. A sound elemental with a room-wide pull followed by a detonation players must run out of.', 'murmur,auchindoun: shadow labyrinth', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_chief_ukorz_sandscalp', 'Chief Ukorz Sandscalp', 'Chief Ukorz Sandscalp is the final boss of Zul''Farrak, a level 43 to 46 five-player dungeon in Tanaris. The Sandfury chief, reached after the pyramid steps event.', 'chief ukorz sandscalp,zul''farrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_princess_theradras', 'Princess Theradras', 'Princess Theradras is the final boss of Maraudon, a level 41 to 48 five-player dungeon in Desolace. An earth elemental princess at the bottom of the pristine waters wing.', 'princess theradras,maraudon', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_gordok', 'King Gordok', 'King Gordok is the final boss of the north wing of Dire Maul, a level 55 to 60 five-player dungeon in Feralas. Killing him grants the ogre suit tribute run, which is why players clear the wing carefully.', 'king gordok,dire maul', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_drakkisath', 'General Drakkisath', 'General Drakkisath is the final boss of the upper wing of Blackrock Spire, a level 57 to 63 five- and ten-player dungeon in Blackrock Mountain. He guards the orb used for the old Onyxia attunement chain.', 'general drakkisath,blackrock spire', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mutanus_the_devourer', 'Mutanus the Devourer', 'Mutanus the Devourer is the final boss of Wailing Caverns, a level 17 to 20 five-player dungeon in the Barrens. He appears at the end of the escort event that the whole dungeon leads up to.', 'mutanus the devourer,wailing caverns', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_amnennar_the_coldbringer', 'Amnennar the Coldbringer', 'Amnennar the Coldbringer is the final boss of Razorfen Downs, a level 34 to 37 five-player dungeon in the Southern Barrens. A lich raising the quilboar dead, and the highest-level threat in the warrens.', 'amnennar the coldbringer,razorfen downs', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_herod', 'Herod', 'Herod is the final boss of the Armory wing of Scarlet Monastery, a level 29 to 40 five-player dungeon in Tirisfal Glades. The Scarlet champion, who whirlwinds across the room and then flees to pull the training hall.', 'herod,scarlet monastery', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_high_inquisitor_whitemane', 'High Inquisitor Whitemane', 'High Inquisitor Whitemane is the final boss of the Cathedral wing of Scarlet Monastery, a level 29 to 40 five-player dungeon in Tirisfal Glades. She resurrects Scarlet Commander Mograine once, so both have to be brought down together.', 'high inquisitor whitemane,scarlet monastery', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_rules_general', 'Capital Cities', 'Capital cities are safe hubs, not leveling ground. They contain no hostile mobs to kill and no quest grinding areas. Dueling is disabled inside city limits, so players who want to duel step outside the gates first. Every capital has a bank, auction house, mailbox, inn with an innkeeper for setting your hearthstone, flight master, stable master, guild master, barber shop, and the full set of class and profession trainers. Resting in a city accumulates rested experience faster than resting in the wild.', 'capital,capital city,city,cities,cannot duel,dueling disabled,duel,rested experience,barber shop', 'city,mechanics,safe_zone');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_stormwind', 'Stormwind City', 'Stormwind City is the human capital and the main Alliance hub in the Eastern Kingdoms, sitting in the north of Elwynn Forest. It is divided into the Trade District, Old Town, the Mage Quarter, Cathedral Square, the Dwarven District, and the Park, with the Valley of Heroes at the front gates. King Varian Wrynn rules from Stormwind Keep. The Deeprun Tram runs underground from the Dwarven District to Ironforge, and the harbor carries boats to Northrend and Kalimdor.', 'stormwind,stormwind city,human capital,alliance capital,trade district,old town,mage quarter,cathedral square,dwarven district,valley of heroes,stormwind keep,varian wrynn,deeprun tram,stormwind harbor,sw', 'city,alliance,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_ironforge', 'Ironforge', 'Ironforge is the dwarven capital, carved into the mountain of Dun Morogh and centered on the Great Forge. Its districts include the Commons, Tinker Town, the Mystic Ward, the Military Ward, and the Hall of Explorers, which houses the Explorers'' League and the museum. King Magni Bronzebeard rules here. The Deeprun Tram connects Ironforge to Stormwind, and the gryphon roost handles Alliance flight paths across the Eastern Kingdoms.', 'ironforge,dwarven capital,dwarf capital,great forge,tinker town,mystic ward,military ward,hall of explorers,explorers league,magni bronzebeard,deeprun tram,gryphon roost', 'city,alliance,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_darnassus', 'Darnassus', 'Darnassus is the night elf capital, built among the branches of Teldrassil across the sea in northern Kalimdor. Its districts include the Temple of the Moon, the Cenarion Enclave, the Craftsmen''s Terrace, the Warrior''s Terrace, and the Tradesmen''s Terrace. High Priestess Tyrande Whisperwind leads from the temple. Players reach it through the portal at Rut''theran Village at the base of the tree, which also connects by boat to Darkshore and Azuremyst Isle.', 'darnassus,night elf capital,temple of the moon,cenarion enclave,craftsmens terrace,warriors terrace,tyrande whisperwind,rutheran village,teldrassil capital', 'city,alliance,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_exodar', 'The Exodar', 'The Exodar is the draenei capital, a crashed naaru vessel embedded in the western edge of Azuremyst Isle off the coast of Kalimdor. Its wings include the Trader''s Tier, the Crystal Hall, the Vault of Lights, and the Seat of the Naaru, where Prophet Velen resides. It is the least-trafficked Alliance capital, and a boat from Azuremyst Isle connects it to Darnassus and the rest of Kalimdor.', 'exodar,the exodar,draenei capital,traders tier,crystal hall,vault of lights,seat of the naaru,velen,prophet velen,azuremyst capital', 'city,alliance,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_orgrimmar', 'Orgrimmar', 'Orgrimmar is the orc capital and the main Horde hub, built into the canyons of Durotar. Its districts are the Valley of Strength, the Valley of Honor, the Valley of Wisdom, the Valley of Spirits, the Drag, and the Cleft of Shadow, where warlocks and rogues train and the entrance to Ragefire Chasm sits. Warchief Thrall rules from Grommash Hold. Zeppelin towers outside the gates run to Undercity, Grom''gol in Stranglethorn, and Northrend.', 'orgrimmar,orc capital,horde capital,valley of strength,valley of honor,valley of wisdom,valley of spirits,cleft of shadow,the drag,grommash hold,thrall,warchief,zeppelin tower,og,org', 'city,horde,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_thunder_bluff', 'Thunder Bluff', 'Thunder Bluff is the tauren capital, a cluster of mesas rising above the plains of Mulgore and joined by rope bridges and wooden elevators. Elder Rise, Spirit Rise, and Hunter Rise ring the central High Rise, where Cairne Bloodhoof leads. It is the Horde''s center for shamanism, druidism, and leatherworking, and the long fall from its bridges is a hazard for players who miss the lift.', 'thunder bluff,tauren capital,mulgore capital,elder rise,spirit rise,hunter rise,high rise,cairne bloodhoof,mesa,rope bridges,elevators,tb', 'city,horde,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_undercity', 'Undercity', 'Undercity is the Forsaken capital, built in the catacombs beneath the ruined city of Lordaeron in Tirisfal Glades. It is laid out as a ring of quarters around a central well: the Trade Quarter, the War Quarter, the Magic Quarter, the Rogues'' Quarter, and the Apothecarium, where Lady Sylvanas Windrunner and the Royal Apothecary Society plot. A zeppelin tower outside the ruins connects it to Orgrimmar and Northrend.', 'undercity,forsaken capital,undead capital,lordaeron,ruins of lordaeron,trade quarter,war quarter,magic quarter,rogues quarter,apothecarium,sylvanas windrunner,royal apothecary society,uc', 'city,horde,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_silvermoon', 'Silvermoon City', 'Silvermoon City is the blood elf capital in northern Eversong Woods, the last great city of Quel''Thalas. Its districts include the Royal Exchange, the Bazaar, the Walk of Elders, and Sunfury Spire, where Lor''themar Theron rules as regent. It is the most remote Horde capital: players usually arrive through the orb of translocation linking Undercity to Silvermoon, rather than travelling overland through the Ghostlands.', 'silvermoon,silvermoon city,blood elf capital,quelthalas,royal exchange,the bazaar,walk of elders,sunfury spire,lorthemar theron,orb of translocation', 'city,horde,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_shattrath', 'Shattrath City', 'Shattrath City is the neutral hub of Outland, in western Terokkar Forest, where both factions trade and quest side by side. It is a sanctuary: all player versus player combat is disabled inside, including dueling. The Terrace of Light holds the naaru A''dal and portals to every capital city, while the Lower City below is home to refugees and the Sha''tar''s quartermasters. Players choose between the Aldor and the Scryers here, and the choice locks out the other faction''s rewards.', 'shattrath,shattrath city,outland hub,neutral city,sanctuary,no pvp,terrace of light,lower city,adal,the shatar,aldor,scryers,terokkar,shatt', 'city,neutral,outland,sanctuary');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_dalaran', 'Dalaran', 'Dalaran is the neutral magical city of Northrend, floating above Crystalsong Forest, and the main hub for level 75 and above. Like Shattrath it is a sanctuary, so faction combat and dueling are disabled in the streets above. Runeweaver Square holds portals to every capital, and the Violet Citadel houses the Kirin Tor under Rhonin. The exception is the Underbelly, the sewer level beneath the city, where free-for-all combat is allowed and players do fight.', 'dalaran,northrend hub,floating city,neutral city,sanctuary,kirin tor,runeweaver square,violet citadel,rhonin,the underbelly,dalaran sewers,crystalsong forest,dal', 'city,neutral,northrend,sanctuary');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_warrior', 'Warrior Class', 'Warriors are melee fighters who run on rage, built by dealing and taking damage, and switch between Battle, Defensive and Berserker stances. Their trees are Arms and Fury for damage and Protection for tanking. They wear mail until level 40 and plate after, and every race except blood elves can be one.', 'warrior,rage,stance,stances,battle stance,berserker stance,defensive stance,charge,intercept,taunt,heroic strike,execute,challenging shout', 'class,melee,tank,dps,versatile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_paladin', 'Paladin Class', 'Paladins are plate-wearing holy warriors who run on mana: Holy heals, Protection tanks and Retribution deals melee damage. They buff the group with blessings and auras, use seals and judgements in combat, and carry Divine Shield. The races that can be paladins are humans, dwarves, draenei and blood elves.', 'paladin,pally,blessing,blessings,judgement,judgment,divine shield,seal of', 'class,hybrid,healer,tank,dps');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_hunter', 'Hunter Class', 'Hunters fight at range with bows, guns or crossbows, which still use arrows or bullets in Wrath, and keep a tamed beast as a pet. They run on mana, wear mail from level 40, and use traps, aspects and Feign Death. Their trees are Beast Mastery, Marksmanship and Survival.', 'hunter,huntard,traps,feign death,misdirection,aspect of the hawk,aspect of the dragonhawk,deterrence,disengage', 'class,ranged,dps,pets,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_rogue', 'Rogue Class', 'Rogues are leather-wearing melee fighters who run on energy and build combo points to spend on finishers like Eviscerate. They can stealth, sap, pick locks and apply poisons bought from poison vendors. Their trees are Assassination, Combat and Subtlety.', 'rogue,energy,combo points,stealth,vanish,sprint,backstab,sap,kidney shot,eviscerate,cloak of shadows', 'class,melee,dps,stealth,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_priest', 'Priest Class', 'Priests wear cloth and run on mana: Discipline and Holy heal and Shadow deals damage from Shadowform. Their utility includes Power Word: Fortitude, Fear Ward, Mind Control and resurrection. The races that can be priests are humans, dwarves, night elves, draenei, undead, trolls and blood elves.', 'priest,mind control,psychic scream,fear ward,power word fortitude,shackle undead', 'class,caster,healer,dps,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_shaman', 'Shaman Class', 'Shamans run on mana, wear mail from level 40, and drop totems that buff the group; Bloodlust, called Heroism for the Alliance, speeds up the whole party. Elemental casts, Enhancement fights in melee and Restoration heals, and Reincarnation lets them revive themselves. Only four races can be shamans: orcs, tauren, trolls and draenei.', 'shaman,shammy,totem,totems,bloodlust,heroism,reincarnation,ankh,ghost wolf,purge', 'class,hybrid,healer,dps,elemental');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_mage', 'Mage Class', 'Mages wear cloth, like warlocks and priests, and run on mana: Arcane, Fire and Frost are their three damage trees. They polymorph enemies, conjure food and water, teleport themselves to capitals from level 20 and open portals for others from 40.', 'mage,polymorph,sheep,teleport,blink,counterspell', 'class,caster,ranged,dps,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_warlock', 'Warlock Class', 'Warlocks wear cloth, like mages and priests, and run on mana plus soul shards. Affliction, Demonology and Destruction are their three damage trees, and they summon demons such as the imp, voidwalker, succubus and felhunter. They make healthstones and soulstones and can summon party members with Ritual of Summoning, which needs two helpers to click the portal.', 'warlock,lock,summon,summoning,soulstone,healthstone', 'class,caster,dps,demonic,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_druid', 'Druid Class', 'Druids shapeshift and wear leather: Balance casts in Moonkin Form, Feral fights as a cat or tanks as a bear, and Restoration heals, the only class that can tank, heal or deal damage in either melee or ranged. Rebirth revives an ally in combat and Innervate restores mana. Only two races can be druids: night elves and tauren.', 'druid,shapeshift,shapeshifting,travel form,flight form,innervate,rebirth,brez,battle rez,hibernate,cyclone,entangling roots', 'class,hybrid,versatile,shapeshift');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_death_knight', 'Death Knight Class', 'Death Knights are Wrath''s plate-wearing hero class: they start at level 55 in Ebon Hold and need a level 55 character on the realm to create. They run on runes and runic power, and Blood, Frost and Unholy can each tank or deal damage. Death Grip pulls an enemy to them, and every race can be one.', 'death knight,dk,deathknight,death grip,anti magic shell,antimagic shell,death coil,icy touch,plague strike,blood strike,army of the dead,lichborne,dks', 'class,melee,tank,dps,undead');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_factions_alliance', 'Alliance Faction', 'The Alliance is one of the two major factions in Azeroth, consisting of noble and honorable races united against the Horde. Member races include Humans, Dwarves, Gnomes, Night Elves, and Draenei. The Alliance values honor, tradition, and protecting Azeroth from threats. Their capital cities include Stormwind, Ironforge, Darnassus, and the Exodar. Alliance players work together to maintain peace and order.', 'alliance,alliance races,alliance side,alliance capitals', 'faction,alliance,races,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_factions_horde', 'Horde Faction', 'The Horde is a powerful faction of warrior races who fight for survival and strength. Member races include Orcs, Trolls, Tauren, Undead (Forsaken), and Blood Elves. The Horde values strength, honor in battle, and protecting their way of life. Their capital cities include Orgrimmar, Thunder Bluff, Undercity, and Silvermoon City. Horde players are fierce warriors who respect strength and combat prowess.', 'horde,horde races,horde side,horde capitals,for the horde', 'faction,horde,races,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_humans', 'Human Race', 'Humans are the most widespread and adaptable race in Azeroth, known for their resilience and determination. They founded the Alliance and built the mighty kingdom of Stormwind. Humans excel at all classes and are known for their diplomacy and leadership. Key traits include the Human Spirit (+3% Spirit) and Diplomacy (+10% reputation gains with every faction). Humans start in Elwynn Forest and have access to mounts at level 20.', 'human,humans,human racial,diplomacy,every man for himself,human spirit', 'race,alliance,human,versatile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_orcs', 'Orc Race', 'Orcs are fierce and honorable warriors from Draenor, brought to Azeroth through the Dark Portal. They form the backbone of the Horde and value strength and combat prowess above all. Orcs have Command (+5% pet damage), Axe Specialization, Hardiness (reduced stun duration), and the activated Blood Fury racial. They start in Durotar and have a rich history of shamanism and warfare. Notable orcs include Thrall, Garrosh Hellscream, and Grommash Hellscream.', 'orc,orcs,orc racial,blood fury,hardiness,axe specialization', 'race,horde,orc,warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_dwarves', 'Dwarf Race', 'Dwarves are stout, bearded mountain dwellers known for their craftsmanship and love of ale. They are master miners, blacksmiths, and engineers. Dwarves have Gun Specialization, Mace Specialization, passive Frost Resistance, and the activated Stoneform racial, which cures poison, disease, and bleed effects. They start in Dun Morogh and are fiercely loyal to the Alliance. Dwarves excel at warrior, priest, and hunter classes. Famous dwarves include King Magni Bronzebeard and Muradin Bronzebeard.', 'dwarf,dwarves,dwarf racial,stoneform,gun specialization,find treasure', 'race,alliance,dwarf,craftsman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_night_elves', 'Night Elf Race', 'Night Elves are ancient, immortal beings who protect the natural world of Azeroth. They are master druids, hunters, and warriors with a deep connection to nature. Night Elves have Quickness (melee and ranged attackers are 2% less likely to hit them), Nature Resistance (2% less likely to be hit by Nature spells), and Shadowmeld, an activated near-invisibility used while standing still; on death they briefly become a fast-moving wisp. They start on the sacred tree of Teldrassil and are devoted to Elune. Night Elves excel at druid, hunter, and priest classes. Key figures include Tyrande Whisperwind and Malfurion Stormrage.', 'night elf,night elves,nelf,nelfs,night elf racial,shadowmeld,quickness,wisp spirit,elune', 'race,alliance,night elf,nature');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_tauren', 'Tauren Race', 'Tauren are massive, peaceful nomads from the plains of Mulgore, devoted to the spirits of nature. They are natural shamans and druids with a deep spiritual connection to the elements. Tauren have Endurance (+5% base health), War Stomp (an activated stun on nearby enemies), Cultivation (+15 Herbalism skill), and Nature Resistance (2% less likely to be hit by Nature spells). They start in Mulgore and have a rich culture of storytelling and herbalism. Tauren excel at druid, shaman, and warrior classes. Cairne Bloodhoof is the tauren high chieftain, ruling from Thunder Bluff.', 'tauren,tauren racial,war stomp,endurance,cultivation', 'race,horde,tauren,spiritual');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_trolls', 'Troll Race', 'Trolls are fierce jungle warriors from the islands of the South Seas, known for their regeneration and voodoo magic. They are agile hunters and warriors with a tribal culture. Trolls have Berserking (an activated 20% attack and casting speed burst, a flat amount since the Wrath revamp), Regeneration (faster health regen that partly continues in combat), and Beast Slaying (+5% damage to Beasts). They start in Durotar alongside the orcs. Trolls excel at hunter, mage, priest, rogue, shaman, and warrior classes. Notable trolls include Vol''jin and Zul''jin.', 'troll,trolls,troll racial,berserking,regeneration,beast slaying,darkspear', 'race,horde,troll,agile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_gnomes', 'Gnome Race', 'Gnomes are ingenious tinkerers and inventors from the underground city of Gnomeregan. They are brilliant engineers and mages with a love for technology. Gnomes have Expansive Mind (+5% intellect), a 2% reduced chance to be hit by arcane spells (Arcane Resistance), and Engineering Specialization (+15 engineering skill). They start in Dun Morogh and are loyal Alliance members. Gnomes excel at mage, rogue, and warrior classes. Famous gnomes include High Tinker Mekkatorque and Sicco Thermaplugg.', 'gnome,gnomes,gnome racial,escape artist,expansive mind,engineering specialization', 'race,alliance,gnome,ingenious');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_forsaken', 'Forsaken (Undead) Race', 'The Forsaken are undead beings who broke free from the Scourge, fighting for their freedom. They are cunning rogues and warlocks with resistance to fear and sleep. Forsaken have Will of the Forsaken (removes fear, sleep, and charm effects), Cannibalize (health regen from nearby corpses), and passive Shadow Resistance. They start in Tirisfal Glades and rule the Undercity. Forsaken excel at rogue, warlock, priest, mage, and warrior classes. Queen Sylvanas Windrunner leads the Forsaken.', 'forsaken,undead,undead racial,will of the forsaken,wotf,cannibalize', 'race,horde,undead,forsaken');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_blood_elves', 'Blood Elf Race', 'Blood Elves are magically addicted survivors of the fallen kingdom of Quel''Thalas. They are powerful mages and paladins with a thirst for magic. Blood Elves have Arcane Torrent (a silence that also restores mana, energy, runic power, or rage), Arcane Affinity (+10 Enchanting skill), and passive Magic Resistance. They start in Eversong Woods and are ruled from Silvermoon by Regent Lord Lor''themar Theron; Kael''thas Sunstrider betrayed them and is now an enemy. Blood Elves excel at mage, paladin, priest, rogue, hunter, and warlock classes.', 'blood elf,blood elves,belf,belfs,blood elf racial,arcane torrent,arcane affinity', 'race,horde,blood elf,magical');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_draenei', 'Draenei Race', 'Draenei are a tailed, hooved alien race who crashed on Azeroth fleeing demonic pursuers. They are holy paladins and priests with a devotion to the Light. Draenei have Heroic Presence (+1% hit chance for themselves and their party), Gift of the Naaru (an activated heal-over-time), and Gemcutting (+5 Jewelcrafting skill). They start on Azuremyst Isle and have advanced technology. Draenei excel at paladin, priest, shaman, mage, hunter, and warrior classes. Prophet Velen leads the draenei.', 'draenei,draenei racial,gift of the naaru,heroic presence,gemcutting', 'race,alliance,draenei,holy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_leveling_guide', 'Leveling Strategies', 'Resting in an inn or a capital city builds rested experience, which doubles the experience from kills until it runs out. From level 15 the Dungeon Finder queues random dungeons, which pay well for leveling, and bind-to-account heirloom shoulders and chests add 10% experience each. The level cap is 80; Death Knights start at 55.', 'leveling,level up,lvling,xp,exp,rested xp,rested experience,leveling fast,heirloom,heirlooms,level fast,fastest leveling', 'general,leveling,progression,efficiency');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_gold_making', 'Gold Making Methods', 'Steady gold at 80 comes from daily quests, up to 25 a day, and from gathering: Saronite and Titanium ore, Frost Lotus and Lichbloom, and Frostweave Cloth always sell on the auction house. Crafters earn by selling glyphs, cut gems, flasks and enchanting materials like Infinite Dust.', 'gold making,make gold,farm gold,gold farming,earn gold,making money,money', 'general,economy,gold,professions');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_ui_customization', 'Interface Customization', 'Interface Options in the Escape menu can turn on four extra action bars beside the main one, and Key Bindings lets you put any spell on any key. /macro opens the macro window, with 36 general macros shared by the account and 18 more per character.', 'ui,interface,interface options,action bars,action bar,key bindings,keybinds,keybind,macro,macros', 'general,interface,customization,addons');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_addons', 'Essential Addons', 'Popular 3.3.5 addons: Deadly Boss Mods or BigWigs for boss timers, Omen for threat, Recount or Skada for damage meters, QuestHelper or Carbonite for quest routes, Auctioneer or Auctionator for the auction house, Gatherer for herb and ore nodes, and Bartender4 for action bars. An addon has to be the 3.3.5 version (interface 30300); retail builds won''t load. Each addon installs as its own folder in Interface\\AddOns.', 'addons,addon,dbm,deadly boss mods,bigwigs,recount,skada,omen,questhelper,auctioneer,auctionator,gatherer,bartender,damage meter,threat meter', 'general,addons,tools,enhancement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_server_population', 'Server Types and Population', 'On a PvP realm, entering a contested zone flags you for PvP automatically, so enemy players can attack you anywhere outside your own faction''s zones and sanctuaries. On a PvE realm you can only be attacked once you flag yourself with /pvp or attack an enemy player; the flag wears off five minutes after you turn it off.', 'pvp server,pve server,pvp realm,pve realm,realm type,server type,pvp flag,flagged,pvp flagged', 'general,servers,population,rules');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_character_creation', 'Character Creation Tips', 'You can play ten races: Alliance humans, dwarves, gnomes, night elves and draenei; Horde orcs, trolls, tauren, undead and blood elves. Only night elves and tauren can be druids, shamans are orcs, trolls, tauren or draenei, and paladins are humans, dwarves, draenei or blood elves. A Death Knight unlocks once you have a level 55 character on the realm.', 'character creation,new character,make a character,create a character,reroll,race and class,which race,what race,race class combo', 'general,character,creation,planning');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_gear_optimization', 'Gear Optimization', 'Gear is tuned with gems and enchants, including the off-hand. Head enchants are arcanums sold at Revered by factions like the Argent Crusade, Kirin Tor and Knights of the Ebon Blade; shoulder inscriptions come from the Sons of Hodir at Honored and Exalted; and a blacksmith''s Eternal Belt Buckle adds one more socket to any belt.', 'gear,gearing,stat priority,stats,upgrade,upgrades,bis,best in slot,arcanum,head enchant,shoulder enchant,inscription for shoulders,belt buckle,eternal belt buckle,gem,off,offhand', 'general,gear,optimization,stats');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_patch_changes', 'Understanding Patches', 'The realm runs patch 3.3.5a, the final patch of Wrath of the Lich King. Patch 3.3 added Icecrown Citadel, the Forge of Souls, Pit of Saron and Halls of Reflection dungeons and the Dungeon Finder, and 3.3.5 added the Ruby Sanctum raid against Halion.', 'patch,patches,patch notes,335,nerf,nerfs,nerfed,expansion', 'general,patches,updates,balance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_achievement_hunting', 'Achievement Collecting', 'The big meta achievements pay mounts: Glory of the Hero (heroic dungeon feats) gives the Red Proto-Drake, Glory of the Raider gives the Black Proto-Drake on 10-player and the Plagued Proto-Drake on 25, Glory of the Ulduar Raider gives the Rusted or Ironbound Proto-Drake, and What a Long, Strange Trip It''s Been, for every holiday meta, gives the Violet Proto-Drake.', 'achievement hunting,meta achievement,glory of the hero,glory of the raider,glory of the ulduar raider,glory of the icecrown raider,what a long strange trip,proto drake,achievement mount', 'general,achievements,goals,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_alt_management', 'Managing Multiple Characters', 'You can have up to 10 characters on a realm and 50 across the account. Bind-to-account heirlooms can be mailed between your characters on the realm, and a Death Knight unlocks once one of them reaches level 55. Many players park a bank alt in a capital to hold materials and run auctions.', 'alt,alts,altoholic,bank alt,alt character,character slots,how many characters', 'general,alts,management,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_endgame_content', 'Endgame and Raids', 'At level 80 the endgame is heroic five-mans, raids, arenas, Wintergrasp, daily quests and reputation. The raids are Naxxramas, Obsidian Sanctum, Eye of Eternity, Vault of Archavon, Ulduar, Trial of the Crusader, Onyxia''s Lair, Icecrown Citadel and Ruby Sanctum; Icecrown Citadel is the top tier and ends with the Lich King.', 'endgame,end game,max level,level cap,raids', 'general,endgame,content,variety');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_learning_basics', 'Learning the Basics', 'New characters start at level 1 in their race''s starting zone. Class trainers in towns and capitals teach new spells and ranks every two levels for gold. Talent points start at level 10, riding at 20, and dual specialization at 40; the cap is 80.', 'new player,beginner,just started,how to play,basics', 'general,basics,learning,beginners');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_finding_groups', 'Finding Groups for Content', 'The Dungeon Finder builds a group for five-man dungeons automatically, cross-realm. Raids aren''t queued: they''re formed in trade chat, the LookingForGroup channel or the Raid Browser, where you list yourself for a raid and leaders can invite you. Saying your role and gear level up front gets invites faster.', 'looking for group,lfg,lfm,find a group,find group,pug,pugs,raid browser,lookingforgroup', 'general,groups,social,content');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_addon_management', 'Managing Addons Effectively', 'Addons go in World of Warcraft\\Interface\\AddOns, one folder per addon, and are switched on per character from the AddOns button on the character select screen; tick Load out of date AddOns if one is flagged out of date. Their settings are saved in the WTF folder, so copying it backs up your setup, and /reload reloads the interface.', 'install addons,install addon,addon folder,out of date addons,load out of date,wtf folder,reload ui,reloadui,addon broken', 'general,addons,management,technical');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_questing_efficiency', 'Questing Efficiently', 'Since patch 3.3 the world map and minimap show where each tracked quest''s objectives are, so a quest addon is optional. The quest log holds 25 quests, and up to 25 daily quests can be completed per day. Picking up every quest in a hub before heading out saves the most travel.', 'questing,quest tracking,quest objectives,quest map,daily cap,quest tracker', 'general,questing,efficiency,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_inventory_management', 'Managing Inventory and Bags', 'Characters carry a backpack plus four bag slots; tailors make the 20-slot Frostweave Bag, and profession bags hold more but only their own material. The bank adds 28 slots and seven more bag slots bought with gold. Items have no weight, only slot count matters.', 'bags,bag,bag space,inventory,inventory full,bag slots,bigger bags,frostweave bag,profession bag', 'general,inventory,management,organization');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_reputation_grinding', 'Reputation Grinding Strategies', 'In Northrend, wearing the tabard of the Argent Crusade, Kirin Tor, Knights of the Ebon Blade or Wyrmrest Accord in a level-80 dungeon sends that dungeon''s reputation to the faction, called championing. Factions without a tabard, like the Sons of Hodir, rise only through quests and dailies, and humans gain 10% more reputation from Diplomacy.', 'rep grind,reputation grind,grind rep,rep farm,farm rep,championing,champion tabard,kirin tor rep,hodir rep,sons of hodir rep,diplomacy', 'general,reputation,grinding,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_raid_preparation', 'Preparing for Raids', 'Raiders bring a flask, which lasts an hour and stays through death, plus food; a cook''s Fish Feast feeds the whole raid at once. Repair before the first pull, and since raid lockouts reset once a week, check whether the group is on a fresh or a saved raid ID before joining.', 'raid prep,raid ready,pre raid,fish feast,raid consumables,raid requirements', 'general,raids,preparation,strategy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_pvp_preparation', 'PvP Preparation Tips', 'For PvP, wear gear with resilience, which cuts critical strikes and damage taken from players, and carry the PvP trinket: the Medallion of the Alliance or Medallion of the Horde. It breaks stuns, fears and other crowd control on a 2-minute cooldown; humans'' Every Man for Himself does the same.', 'pvp trinket,medallion of the alliance,medallion of the horde,pvp prep,break cc,cc break', 'general,pvp,preparation,combat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_utgarde_keep', 'Utgarde Keep', 'Utgarde Keep is a level 69 to 72 five-player dungeon in Howling Fjord. It is the first dungeon most players see in Northrend, a vrykul hold built into the cliffs above Daggercap Bay. Its bosses are Prince Keleseth, Dalronn the Controller, and Ingvar the Plunderer.', 'utgarde keep,uk,utgarde', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_nexus', 'The Nexus', 'The Nexus is a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. It is the middle ring of Malygos''s spire, and the whole place is frozen blue crystal. Its bosses are Commander Stoutbeard, Grand Magus Telestra, Anomalus, Ormorok the Tree-Shaper, and Keristrasza.', 'the nexus,nexus', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_azjol_nerub', 'Azjol-Nerub', 'Azjol-Nerub is a level 72 to 74 five-player dungeon in Dragonblight. It is a short three-boss run straight down through the old nerubian kingdom, and the second boss fight happens while you retreat up a web tunnel. Its bosses are Krik''thir the Gatewatcher, Hadronox, and Anub''arak.', 'azjol nerub,azjol-nerub,an,nerub', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ahn_kahet_the_old_kingdom', 'Ahn''kahet: The Old Kingdom', 'Ahn''kahet: The Old Kingdom is a level 73 to 75 five-player dungeon in Dragonblight. It shares an entrance area with Azjol-Nerub but runs deeper and darker, and Amanitar only appears on heroic difficulty. Its bosses are Elder Nadox, Prince Taldaram, Jedoga Shadowseeker, Amanitar, and Herald Volazj.', 'ahnkahet,the old kingdom,old kingdom,ok', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_drak_tharon_keep', 'Drak''Tharon Keep', 'Drak''Tharon Keep is a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. It is a Drakkari troll fortress, and King Dred at the end is a devilsaur kept as a pet. Its bosses are Trollgore, Novos the Summoner, and King Dred.', 'draktharon keep,draktharon,dtk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_violet_hold', 'Violet Hold', 'Violet Hold is a level 75 to 77 five-player dungeon in Dalaran. It is a prison break rather than a crawl: you hold a room against timed waves while sealed cells open, and which mini-bosses you get is randomised each run. Its bosses are Erekem, Moragg, Ichoron, Xevozz, Lavanthor, Zuramat the Obliterator, and Cyanigosa.', 'violet hold,vh', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gundrak', 'Gundrak', 'Gundrak is a level 76 to 78 five-player dungeon in Zul''Drak. It is where the Drakkari are butchering their own animal gods, and Eck the Ferocious is a bonus boss that only exists on heroic. Its bosses are Slad''ran, Moorabi, Drakkari Colossus, Gal''darah, and Eck the Ferocious.', 'gundrak,gd', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_stone', 'Halls of Stone', 'Halls of Stone is a level 77 to 79 five-player dungeon in The Storm Peaks. The middle of it is the Tribunal of Ages, an escort-and-defend event where Brann Bronzebeard reads titan records while you keep him alive. Its bosses are Krystallus, Maiden of Grief, and Sjonnir The Ironshaper.', 'halls of stone,hos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_lightning', 'Halls of Lightning', 'Halls of Lightning is a level 79 to 80 five-player dungeon in The Storm Peaks. It sits above Halls of Stone in the same titan complex, and Loken at the end is a straight damage race against a stacking pulse. Its bosses are General Bjarngrim, Volkhan, Ionar, and Loken.', 'halls of lightning,hol', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_utgarde_pinnacle', 'Utgarde Pinnacle', 'Utgarde Pinnacle is a level 79 to 80 five-player dungeon in Howling Fjord. It is the upper half of the same vrykul keep as Utgarde Keep but tuned for level 80, and Skadi is fought from the back of a drake. Its bosses are Svala Sorrowgrave, Gortok Palehoof, Skadi the Ruthless, and King Ymiron.', 'utgarde pinnacle,up,pinnacle', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_oculus', 'The Oculus', 'The Oculus is a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. Most of it is fought from drake mounts in mid-air, which made it the least popular dungeon in the Dungeon Finder by a wide margin. Its bosses are Drakos the Interrogator, Varos Cloudstrider, Mage-Lord Urom, and Ley-Guardian Eregos.', 'the oculus,oculus,occ', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_culling_of_stratholme', 'The Culling of Stratholme', 'The Culling of Stratholme is a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. It replays Arthas purging Stratholme, and beating the optional timed run rewards the Bronze Drake mount. Its bosses are Meathook, Salramm the Fleshcrafter, Chrono-Lord Epoch, and Mal''Ganis.', 'culling of stratholme,cos,strat cot,bronze drake', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_trial_of_the_champion', 'Trial of the Champion', 'Trial of the Champion is a level 79 to 80 five-player dungeon in the Argent Tournament grounds in Icecrown. It opens with a mounted jousting round using vehicle controls before turning into a normal fight. Its bosses are The Grand Champions, Eadric the Pure, Argent Confessor Paletress, and The Black Knight.', 'trial of the champion,toc5,totc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_forge_of_souls', 'The Forge of Souls', 'The Forge of Souls is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is the first of the three patch 3.3 dungeons that lead into Icecrown Citadel itself. Its bosses are Bronjahm, and Devourer of Souls.', 'forge of souls,fos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_pit_of_saron', 'Pit of Saron', 'Pit of Saron is a level 79 to 80 five-player dungeon in Icecrown Citadel. The last stretch is a scripted escape with Jaina or Sylvanas clearing the way ahead of you. Its bosses are Forgemaster Garfrost, Ick, Krick, and Scourgelord Tyrannus.', 'pit of saron,pos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_reflection', 'Halls of Reflection', 'Halls of Reflection is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is two bosses and then a fighting retreat from the Lich King himself, who cannot be killed here. Its bosses are Falric, Marwyn, and The Lich King.', 'halls of reflection,hor', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_naxxramas', 'Naxxramas', 'Naxxramas is a level 80 ten- and twenty-five-player raid in Dragonblight. It was moved from the Eastern Plaguelands and retuned for level 80 as Wrath''s entry raid; it is split into the Arachnid, Plague, Military and Construct quarters, which can be cleared in any order before Sapphiron and Kel''Thuzad. Its bosses are Anub''Rekhan, Grand Widow Faerlina, Maexxna, Noth the Plaguebringer, Heigan the Unclean, Loatheb, Instructor Razuvious, Gothik the Harvester, The Four Horsemen, Patchwerk, Grobbulus, Gluth, Thaddius, Sapphiron, and Kel''Thuzad.', 'naxxramas,naxx,scourge,necropolis', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_obsidian_sanctum', 'The Obsidian Sanctum', 'The Obsidian Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. Leaving Sartharion''s three drake lieutenants alive raises the difficulty and the loot, which is where the ''Sartharion plus three drakes'' achievement runs come from. Its bosses are Tenebron, Shadron, Vesperon, and Sartharion.', 'obsidian sanctum,os,sarth', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_eye_of_eternity', 'The Eye of Eternity', 'The Eye of Eternity is a level 80 ten- and twenty-five-player raid in Coldarra, in the Borean Tundra. It is a single fight against Malygos that ends with the whole raid on drakes in a vehicle phase. Its boss is Malygos.', 'eye of eternity,eoe,malygos raid', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ulduar', 'Ulduar', 'Ulduar is a level 80 ten- and twenty-five-player raid in The Storm Peaks. It opens with a vehicle assault on Flame Leviathan, and most bosses have an optional harder ''hard mode'' triggered in-fight rather than by a difficulty setting; Algalon is a limited-attempt bonus encounter. Its bosses are Flame Leviathan, Ignis the Furnace Master, Razorscale, XT-002 Deconstructor, The Assembly of Iron, Kologarn, Auriaya, Hodir, Thorim, Freya, Mimiron, General Vezax, Yogg-Saron, and Algalon the Observer.', 'ulduar,titan,siege of ulduar,inner sanctum', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_trial_of_the_crusader', 'Trial of the Crusader', 'Trial of the Crusader is a level 80 ten- and twenty-five-player raid in the Argent Tournament grounds in Icecrown. It is a single arena room with no trash at all, run as five staged encounters; the Heroic version is separately locked and limited by a shared attempt counter. Its bosses are Northrend Beasts, Lord Jaraxxus, Faction Champions, Twin Val''kyr, and Anub''arak.', 'trial of the crusader,toc,totc25', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_icecrown_citadel', 'Icecrown Citadel', 'Icecrown Citadel is a level 80 ten- and twenty-five-player raid in Icecrown. It is the final raid of Wrath of the Lich King, released wing by wing over patch 3.3, and ends with the Lich King on the roof of the Frozen Throne. Its bosses are Lord Marrowgar, Lady Deathwhisper, Gunship Battle, Deathbringer Saurfang, Festergut, Rotface, Professor Putricide, Prince Valanar, Blood-Queen Lana''thel, Valithria Dreamwalker, Sindragosa, and The Lich King.', 'icecrown citadel,icc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_vault_of_archavon', 'Vault of Archavon', 'Vault of Archavon is a level 80 ten- and twenty-five-player raid in Wintergrasp. Access is a PvP prize rather than a raid lockout: only the faction currently holding Wintergrasp can enter, and each boss drops a mix of PvP and PvE gear. Its bosses are Archavon the Stone Watcher, Emalon the Storm Watcher, Koralon the Flame Watcher, and Toravon the Ice Watcher.', 'vault of archavon,voa,archavon', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_ruby_sanctum', 'The Ruby Sanctum', 'The Ruby Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. It arrived in patch 3.3.5 as the last raid of the expansion, and Halion is fought in both a physical and a shadow version of the room at once. Its bosses are Baltharus the Warborn, General Zarithrian, Saviana Ragefire, and Halion.', 'ruby sanctum,rs,halion', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_onyxia_s_lair', 'Onyxia''s Lair', 'Onyxia''s Lair is a level 80 ten- and twenty-five-player raid in Dustwallow Marsh. Originally a level 60 raid, it was retuned to level 80 in patch 3.2.2 for the game''s fifth anniversary and drops current Wrath-tier loot. Its boss is Onyxia.', 'onyxias lair,onyxia,ony,black dragon,dragonmurk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_ramparts', 'Hellfire Citadel: Ramparts', 'Hellfire Citadel: Ramparts is a level 59 to 62 five-player dungeon in Hellfire Peninsula. It is the first Outland dungeon most players run, and much of it is fought on open walkways rather than corridors. Its bosses are Watchkeeper Gargolmar, Omor the Unscarred, and Vazruden the Herald.', 'hellfire ramparts,ramparts,hfr', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_the_blood_furnace', 'Hellfire Citadel: The Blood Furnace', 'Hellfire Citadel: The Blood Furnace is a level 61 to 63 five-player dungeon in Hellfire Peninsula. It is where the Legion was mass-producing fel orcs, and the middle boss is fought through a sequence of gas-filled cells. Its bosses are The Maker, Broggok, and Keli''dan the Breaker.', 'blood furnace,bf', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_slave_pens', 'Coilfang: The Slave Pens', 'Coilfang: The Slave Pens is a level 62 to 64 five-player dungeon in Zangarmarsh. It is the shallowest of the three Coilfang wings and the usual first stop for a Cenarion Expedition reputation grind. Its bosses are Mennu the Betrayer, Rokmar the Crackler, and Quagmirran.', 'slave pens,sp', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_underbog', 'Coilfang: The Underbog', 'Coilfang: The Underbog is a level 63 to 65 five-player dungeon in Zangarmarsh. The Black Stalker at the bottom is a giant electrified spider that levitates the party. Its bosses are Hungarfen, Ghaz''an, Swamplord Musel''ek, and The Black Stalker.', 'underbog,ub', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_mana_tombs', 'Auchindoun: Mana-Tombs', 'Auchindoun: Mana-Tombs is a level 64 to 66 five-player dungeon in Terokkar Forest. It is the Consortium''s wing of Auchindoun, and the ethereal prince at the end is one of the easier Outland end bosses. Its bosses are Pandemonius, Tavarok, and Nexus-Prince Shaffar.', 'mana tombs,mt', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_auchenai_crypts', 'Auchindoun: Auchenai Crypts', 'Auchindoun: Auchenai Crypts is a level 65 to 67 five-player dungeon in Terokkar Forest. It is full of undead draenei, and Shirrak the Dead Watcher slows casting for the whole room. Its bosses are Shirrak the Dead Watcher, and Exarch Maladaar.', 'auchenai crypts,crypts,ac', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_opening_of_the_dark_portal', 'Opening of the Dark Portal', 'Opening of the Dark Portal is a level 68 to 70 five-player dungeon in the Caverns of Time in Tanaris. Players usually call it the Black Morass. It is a timed defence of Medivh through eighteen portal waves at the moment the Dark Portal was first opened, and it was the attunement step for Karazhan. The Dark Portal itself stands in the Blasted Lands, and this instance is only a vision of its past. Its bosses are Chrono Lord Deja, Temporus, and Aeonus.', 'black morass,bm,opening of the dark portal,cot2', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_sethekk_halls', 'Auchindoun: Sethekk Halls', 'Auchindoun: Sethekk Halls is a level 67 to 68 five-player dungeon in Terokkar Forest. The arakkoa wing of Auchindoun, and on heroic it holds Anzu, the raven god summoned by druids for their flight-form quest. Its bosses are Darkweaver Syth, Talon King Ikiss, and Anzu.', 'sethekk halls,sethekk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_shadow_labyrinth', 'Auchindoun: Shadow Labyrinth', 'Auchindoun: Shadow Labyrinth is a level 69 to 70 five-player dungeon in Terokkar Forest. It is the longest and hardest Auchindoun wing, and Murmur at the end is a sound elemental with a room-wide pull-and-detonate. Its bosses are Ambassador Hellmaw, Blackheart the Inciter, Grandmaster Vorpil, and Murmur.', 'shadow labyrinth,shadow lab,slabs', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_the_shattered_halls', 'Hellfire Citadel: The Shattered Halls', 'Hellfire Citadel: The Shattered Halls is a level 69 to 70 five-player dungeon in Hellfire Peninsula. It has a reputation as the hardest of the Hellfire wings, and its heroic version runs on a timer to rescue prisoners. Its bosses are Grand Warlock Nethekurse, Blood Guard Porung, Warbringer O''mrogg, and Warchief Kargath Bladefist.', 'shattered halls,sh', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_steamvault', 'Coilfang: The Steamvault', 'Coilfang: The Steamvault is a level 69 to 70 five-player dungeon in Zangarmarsh. It is the deepest Coilfang wing and the last step of the old Karazhan-era Cenarion Expedition grind. Its bosses are Hydromancer Thespia, Mekgineer Steamrigger, and Warlord Kalithresh.', 'steamvault,sv', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_mechanar', 'Tempest Keep: The Mechanar', 'Tempest Keep: The Mechanar is a level 69 to 70 five-player dungeon in Netherstorm. It is one of the three satellite wings of Tempest Keep, all mechanical, and the shortest of them. Its bosses are Mechano-Lord Capacitus, Nethermancer Sepethrea, and Pathaleon the Calculator.', 'mechanar,mech', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_botanica', 'Tempest Keep: The Botanica', 'Tempest Keep: The Botanica is a level 69 to 70 five-player dungeon in Netherstorm. It is a greenhouse wing of Tempest Keep, and Warp Splinter at the end summons saplings that must be killed fast. Its bosses are Commander Sarannis, High Botanist Freywinn, Thorngrin the Tender, Laj, and Warp Splinter.', 'botanica,bot', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_arcatraz', 'Tempest Keep: The Arcatraz', 'Tempest Keep: The Arcatraz is a level 69 to 70 five-player dungeon in Netherstorm. It is a prison wing holding things the naaru locked away, and it was the attunement step for the Black Temple. Its bosses are Zereketh the Unbound, Dalliah the Doomsayer, Wrath-Scryer Soccothrates, and Harbinger Skyriss.', 'arcatraz,arc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_magister_s_terrace', 'Magister''s Terrace', 'Magister''s Terrace is a level 69 to 70 five-player dungeon in the Isle of Quel''Danas. It was added in patch 2.4 as the last Burning Crusade dungeon, and its heroic mode drops the Swift White Hawkstrider mount. Its bosses are Selin Fireheart, Vexallus, Priestess Delrissa, and Kael''thas Sunstrider.', 'magisters terrace,mgt,magister''s terrace', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_karazhan', 'Karazhan', 'Karazhan is a level 70 to 73 ten-player raid in Deadwind Pass. It is Medivh''s abandoned tower and the entry raid of the Burning Crusade, known for its chess event and an optional opera encounter that rotates between three scripts. Its bosses are Attumen the Huntsman, Moroes, Maiden of Virtue, Opera Event, The Curator, Terestian Illhoof, Shade of Aran, Netherspite, Chess Event, Prince Malchezaar, and Nightbane.', 'karazhan,kara,kz', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gruul_s_lair', 'Gruul''s Lair', 'Gruul''s Lair is a level 70 twenty-five-player raid in Blade''s Edge Mountains. Two bosses only: a five-ogre council fight and then Gruul himself, who grows in size and damage on a timer. Its bosses are High King Maulgar, and Gruul the Dragonkiller.', 'gruuls lair,gruul', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_magtheridon_s_lair', 'Magtheridon''s Lair', 'Magtheridon''s Lair is a level 70 twenty-five-player raid in Hellfire Peninsula. A single boss beneath Hellfire Citadel, fought while five channelers hold him in place. Its boss is Magtheridon.', 'magtheridons lair,magtheridon,mag', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_serpentshrine_cavern', 'Coilfang: Serpentshrine Cavern', 'Coilfang: Serpentshrine Cavern is a level 70 twenty-five-player raid in Zangarmarsh. It is the raid wing of Coilfang Reservoir and ends with Lady Vashj, whose fight requires relaying tainted cores between phases. Its bosses are Hydross the Unstable, The Lurker Below, Leotheras the Blind, Fathom-Lord Karathress, Morogrim Tidewalker, and Lady Vashj.', 'serpentshrine cavern,ssc,vashj', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep', 'Tempest Keep', 'Tempest Keep is a level 70 twenty-five-player raid in Netherstorm. Usually called The Eye; it is the central spire of Tempest Keep and ends with Kael''thas Sunstrider in a long multi-phase fight. Its bosses are Al''ar, Void Reaver, High Astromancer Solarian, and Kael''thas Sunstrider.', 'tempest keep,the eye,tk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_battle_for_mount_hyjal', 'The Battle for Mount Hyjal', 'The Battle for Mount Hyjal is a level 70 twenty-five-player raid in the Caverns of Time in Tanaris. It replays the battle at the World Tree as eight waves of trash between bosses, which makes it far more trash-heavy than any other raid of its tier. Its bosses are Rage Winterchill, Anetheron, Kaz''rogal, Azgalor, and Archimonde.', 'mount hyjal,hyjal,mh,battle for mount hyjal', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_black_temple', 'Black Temple', 'Black Temple is a level 70 twenty-five-player raid in Shadowmoon Valley. Illidan Stormrage''s fortress and the intended final raid of the Burning Crusade before the Sunwell was added. Its bosses are High Warlord Naj''entus, Supremus, Shade of Akama, Teron Gorefiend, Gurtogg Bloodboil, Reliquary of Souls, Mother Shahraz, The Illidari Council, and Illidan Stormrage.', 'black temple,bt,illidan', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_aman', 'Zul''Aman', 'Zul''Aman is a level 70 to 73 ten-player raid in the Ghostlands. Added in patch 2.3, it runs on a timer: clearing the four animal-god bosses fast enough rewards the Amani War Bear. Its bosses are Akil''zon, Nalorakk, Jan''alai, Halazzi, Hex Lord Malacrass, and Zul''jin.', 'zulaman,za', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_sunwell', 'The Sunwell', 'The Sunwell is a level 70 twenty-five-player raid in the Isle of Quel''Danas. Added in patch 2.4 as the final raid of the Burning Crusade, and its gear was the last tier before Wrath launched. Its bosses are Kalecgos, Brutallus, Felmyst, The Eredar Twins, M''uru, and Kil''jaeden.', 'sunwell plateau,sunwell,swp', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ragefire_chasm', 'Ragefire Chasm', 'Ragefire Chasm is a level 15 to 16 five-player dungeon in Orgrimmar, through the Cleft of Shadow. It is the lowest-level dungeon in the game and the only one inside a capital city. Its bosses are Oggleflint, Taragaman the Hungerer, Jergosh the Invoker, and Bazzalan.', 'ragefire chasm,rfc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_deadmines', 'Deadmines', 'Deadmines is a level 17 to 20 five-player dungeon in Westfall. It runs through a mine and out onto a pirate ship moored in a cavern, and Edwin VanCleef leads the Defias Brotherhood at the end. Its bosses are Rhahk''Zor, Sneed, Gilnid, Mr. Smite, Cookie, Captain Greenskin, and Edwin VanCleef.', 'deadmines,vc,the deadmines,mine cart,van cleef,defias', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_wailing_caverns', 'Wailing Caverns', 'Wailing Caverns is a level 17 to 20 five-player dungeon in the Barrens. It is a maze of twisting tunnels with no clear route, which is most of its reputation. Its bosses are Lady Anacondra, Lord Cobrahn, Kresh, Lord Pythas, Skum, Lord Serpentis, Verdan the Everliving, and Mutanus the Devourer.', 'wailing caverns,wc,naralex,emerald dream', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_shadowfang_keep', 'Shadowfang Keep', 'Shadowfang Keep is a level 18 to 21 five-player dungeon in Silverpine Forest. It is a haunted worgen castle, and the renegade mage Archmage Arugal waits at the top. Its bosses are Rethilgore, Razorclaw the Butcher, Baron Silverlaine, Commander Springvale, Odo the Blindwatcher, Fenrus the Devourer, Wolf Master Nandos, and Archmage Arugal.', 'shadowfang keep,sfk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackfathom_deeps', 'Blackfathom Deeps', 'Blackfathom Deeps is a level 21 to 24 five-player dungeon in Ashenvale. A flooded night elf temple to an old naga-worshipped god, with a long underwater stretch. Its bosses are Ghamoo-ra, Lady Sarevess, Gelihast, Lorgus Jett, Old Serra''kis, Twilight Lord Kelris, and Aku''mai.', 'blackfathom deeps,bfd,twilight hammer', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_stormwind_stockade', 'Stormwind Stockade', 'Stormwind Stockade is a level 22 to 25 five-player dungeon in Stormwind City. A short prison-riot dungeon under the Trade District, and one of the fastest runs in the game. Its bosses are Targorr the Dread, Kam Deepfury, Hamhock, Bazil Thredd, and Dextren Ward.', 'stockade,stocks,stormwind stockade', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_razorfen_kraul', 'Razorfen Kraul', 'Razorfen Kraul is a level 24 to 27 five-player dungeon in the Southern Barrens. An outdoor quilboar warren built from thorns rather than an indoor dungeon. Its bosses are Roogug, Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, Agathelos the Raging, and Charlga Razorflank.', 'razorfen kraul,rfk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gnomeregan', 'Gnomeregan', 'Gnomeregan is a level 25 to 28 five-player dungeon in Dun Morogh. The irradiated gnome capital, and Mekgineer Thermaplugg at the end is fought around a room of bomb-dispensing panels. Its bosses are Grubbis, Viscous Fallout, Electrocutioner 6000, Crowd Pummeler 9-60, and Mekgineer Thermaplugg.', 'gnomeregan,gnomer', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_scarlet_monastery', 'Scarlet Monastery', 'Scarlet Monastery is a level 29 to 40 five-player dungeon in Tirisfal Glades. It is four separate wings behind one entrance -- Graveyard, Library, Armory and Cathedral -- run at increasing levels rather than as one dungeon. Its bosses are Interrogator Vishas, Bloodmage Thalnos, Houndmaster Loksey, Arcanist Doan, Herod, High Inquisitor Fairbanks, and High Inquisitor Whitemane.', 'scarlet monastery,sm,smc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_razorfen_downs', 'Razorfen Downs', 'Razorfen Downs is a level 34 to 37 five-player dungeon in the Southern Barrens. The undead half of the quilboar warrens, ending with the lich Amnennar the Coldbringer. Its bosses are Tuten''kash, Mordresh Fire Eye, Glutton, and Amnennar the Coldbringer.', 'razorfen downs,rfd', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_uldaman', 'Uldaman', 'Uldaman is a level 37 to 40 five-player dungeon in the Badlands. A titan vault, and the first place most players meet the dwarves'' own origin story. Its bosses are Revelosh, Baelog, Ironaya, Ancient Stone Keeper, Galgann Firehammer, Grimlok, and Archaedas.', 'uldaman,ulda', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_maraudon', 'Maraudon', 'Maraudon is a level 41 to 48 five-player dungeon in Desolace. Split into orange, purple and pristine sections with separate entrances, ending at Princess Theradras. Its bosses are Noxxion, Razorlash, Lord Vyletongue, Celebras the Cursed, Landslide, Tinkerer Gizlock, Rotgrip, and Princess Theradras.', 'maraudon,mara,centaur,valley of spears', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_farrak', 'Zul''Farrak', 'Zul''Farrak is a level 43 to 46 five-player dungeon in Tanaris. Best known for the pyramid steps, where a huge troll wave attacks at once, and for Gahz''rilla. Its bosses are Hydromancer Velratha, Antu''sul, Theka the Martyr, Witch Doctor Zum''rah, Nekrum Gutchewer, Chief Ukorz Sandscalp, and Gahz''rilla.', 'zulfarrak,zf,sandfury,antusul', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_sunken_temple', 'Sunken Temple', 'Sunken Temple is a level 47 to 50 five-player dungeon in the Swamp of Sorrows. Properly the Temple of Atal''Hakkar; it is a confusing layered ruin and a long run for its level. Its bosses are Atal''alarion, Dreamscythe, Weaver, Jammal''an the Prophet, Morphaz, Hazzas, and Shade of Eranikus.', 'sunken temple,st,temple of atalhakkar,atal''ai,avatar of hakkar', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackrock_depths', 'Blackrock Depths', 'Blackrock Depths is a level 49 to 56 five-player dungeon in Blackrock Mountain. By far the largest dungeon in the game, with a bar, an arena and a prison inside it, ending at Emperor Dagran Thaurissan. Its bosses are Lord Roccor, High Interrogator Gerstahn, Houndmaster Grebmar, Pyromancer Loregrain, Lord Incendius, Warder Stilgiss, Fineous Darkvire, Bael''Gar, General Angerforge, Golem Lord Argelmach, Ambassador Flamelash, Magmus, and Emperor Dagran Thaurissan.', 'blackrock depths,brd,dark iron,dwarves', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackrock_spire', 'Blackrock Spire', 'Blackrock Spire is a level 57 to 63 five- and ten-player dungeon in Blackrock Mountain. Split into Lower and Upper halves sharing one entrance; Upper was originally a ten-player raid. Its bosses are Highlord Omokk, Shadow Hunter Vosh''gajin, War Master Voone, Mother Smolderweb, Quartermaster Zigris, Halycon, Overlord Wyrmthalak, Pyroguard Emberseer, Warchief Rend Blackhand, The Beast, and General Drakkisath.', 'blackrock spire,lbrs,ubrs,burning steppes,dragonkin', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_dire_maul', 'Dire Maul', 'Dire Maul is a level 55 to 60 five-player dungeon in Feralas. Three separate wings -- East, West and North -- and the North wing has a well-known trick for looting the king''s tribute without killing him. Its bosses are Zevrim Thornhoof, Hydrospawn, Lethtendris, Alzzin the Wildshaper, Illyanna Ravenoak, Magister Kalendris, Immol''thar, Tendris Warpwood, Prince Tortheldrin, Guard Mol''dar, Stomper Kreeg, Guard Fengus, Guard Slip''kik, Captain Kromcrush, Cho''Rush the Observer, and King Gordok.', 'dire maul,dm east,dm west,dm north,warpwood quarter,capital gardens,gordok commons,ogres,pusillin', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_scholomance', 'Scholomance', 'Scholomance is a level 58 to 60 five-player dungeon in the Western Plaguelands. A necromancy school inside Caer Darrow, ending with Darkmaster Gandling. Its bosses are Jandice Barov, Rattlegore, Marduk Blackpool, Vectus, Ras Frostwhisper, Instructor Malicia, Doctor Theolen Krastinov, Lorekeeper Polkelt, The Ravenian, Lord Alexei Barov, Lady Illucia Barov, and Darkmaster Gandling.', 'scholomance,scholo,kirtonos,scourge,caer darrow', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_stratholme', 'Stratholme', 'Stratholme is a level 58 to 60 five-player dungeon in the Eastern Plaguelands. Two separate entrances: the Scarlet side and the undead side, where Baron Rivendare drops the Deathcharger''s Reins on a timed run. Its bosses are The Unforgiven, Hearthsinger Forresten, Timmy the Cruel, Cannon Master Willey, Archivist Galford, Balnazzar, Baroness Anastari, Nerub''enkan, Maleki the Pallid, Ramstein the Gorger, Magistrate Barthilas, and Baron Rivendare.', 'stratholme,strat,live side,baron run,scarlet crusade,scourge,plague', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_molten_core', 'Molten Core', 'Molten Core is a level 60 to 63 forty-player raid in Blackrock Mountain. The game''s first full raid tier, ten bosses ending at Ragnaros, and the source of Tier 1 armour. Its bosses are Lucifron, Magmadar, Gehennas, Garr, Shazzrah, Baron Geddon, Sulfuron Harbinger, Golemagg the Incinerator, Majordomo Executus, and Ragnaros.', 'molten core,mc,fire elementals', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackwing_lair', 'Blackwing Lair', 'Blackwing Lair is a level 60 to 63 forty-player raid in Blackrock Mountain. Nefarian''s lair above Blackrock Spire, and the source of Tier 2 armour. Its bosses are Razorgore the Untamed, Vaelastrasz the Corrupt, Broodlord Lashlayer, Firemaw, Ebonroc, Flamegor, Chromaggus, and Nefarian.', 'blackwing lair,bwl,black dragonflight,drakes', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_gurub', 'Zul''Gurub', 'Zul''Gurub is a level 57 to 63 twenty-player raid in Stranglethorn Vale. A troll city raid on a three-day lockout, ending at the blood god Hakkar. Its bosses are High Priest Venoxis, High Priestess Jeklik, High Priestess Mar''li, Bloodlord Mandokir, Gahz''ranka, High Priest Thekal, High Priestess Arlokk, Jin''do the Hexxer, and Hakkar.', 'zulgurub,zg,gurubashi', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ruins_of_ahn_qiraj', 'Ruins of Ahn''Qiraj', 'Ruins of Ahn''Qiraj is a level 60 to 63 twenty-player raid in Silithus. The smaller of the two Ahn''Qiraj raids, opened by the same war effort as the Temple. Its bosses are Kurinnaxx, General Rajaxx, Moam, Buru the Gorger, Ayamiss the Hunter, and Ossirian the Unscarred.', 'ruins of ahnqiraj,aq20,qiraji,silithid', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ahn_qiraj_temple', 'Ahn''Qiraj Temple', 'Ahn''Qiraj Temple is a level 60 to 63 forty-player raid in Silithus. The larger Ahn''Qiraj raid, ending at C''Thun, and the source of Tier 2.5 armour. Its bosses are The Prophet Skeram, Battleguard Sartura, Fankriss the Unyielding, Viscidus, Princess Huhuran, Twin Emperors, Ouro, and C''Thun.', 'temple of ahnqiraj,aq40,aq,qiraji,silithid', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_tier_sets', 'Tier Sets', 'Each class''s tier set gives a bonus at 2 and at 4 pieces worn. Wrath has Tier 7 from Naxxramas, Tier 8 from Ulduar, Tier 9 from Trial of the Crusader and Tier 10 from Icecrown Citadel. Tier 9 is bought with Emblems of Triumph and Tier 10 with Emblems of Frost, then upgraded with Marks of Sanctification from ICC bosses.', 'tier sets,tier set,tier,t7,t8,t9,t10,set bonus,tier bonus,2pc,4pc,marks of sanctification,tier token,tier tokens', 'items,equipment,raid,tier');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_legendary_weapons', 'Legendary Weapons', 'Wrath''s legendaries are Val''anyr, Hammer of Ancient Kings, a healer''s mace built from 30 Fragments of Val''anyr from 25-player Ulduar, and Shadowmourne, a two-handed axe for warriors, paladins and death knights from a 25-player Icecrown Citadel quest chain. Older ones include Thunderfury, Sulfuras, the Warglaives of Azzinoth from Illidan and Thori''dal from the Sunwell.', 'legendary,legendaries,shadowmourne,valanyr,val anyr,thunderfury,sulfuras,atiesh,warglaives,glaives,thoridal', 'items,weapons,legendary,rare');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_profession_tools', 'Profession Tools', 'Some professions need a tool in the bags before their recipes work: blacksmiths a Blacksmith Hammer, engineers an Arclight Spanner, enchanters a runed rod matched to their skill, miners a Mining Pick and skinners a Skinning Knife. Smithing and smelting also need you standing beside an anvil or a forge. Crafting never fails.', 'profession tool,profession tools,blacksmith hammer,skinning knife,mining pick,runed rod,arclight spanner,anvil,forge', 'items,professions,tools,crafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_mounts_collection', 'Mount Collection', 'Famous rare mount drops include Invincible from the heroic 25-player Lich King, Mimiron''s Head from Yogg-Saron on 25 with no Keepers, the Blue Proto-Drake from Skadi in heroic Utgarde Pinnacle, Ashes of Al''ar from Kael''thas and Deathcharger''s Reins from Baron Rivendare in Stratholme. Owning 50 mounts earns the Albino Drake.', 'mount collection,rare mount,rare mounts,invincible,mimirons head,ashes of alar,deathcharger,deathchargers reins,blue proto drake,albino drake,mount drop,50 mounts,100 mounts', 'items,mounts,collection,rare');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_enchants', 'Weapon and Armor Enchants', 'Enchanters apply enchants directly or onto a scribe''s Armor or Weapon Vellum to make a tradeable scroll; ring enchants are for the enchanter only. Popular Wrath weapon enchants are Berserking and Mongoose for melee, Black Magic for casters and Accuracy for hit. Death knights use Runeforging instead, like Rune of the Fallen Crusader or Razorice, at a runeforge in Ebon Hold.', 'enchant,enchants,weapon enchant,mongoose,black magic,enchant scroll,vellum,runeforge,runeforging,fallen crusader,razorice,crusader enchant', 'items,enchants,enchanting,improvement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_gems', 'Socketed Gems', 'Sockets are red, yellow, blue or meta. Red gems carry strength, agility, attack power or spell power; yellow carry crit, haste or hit; blue carry stamina, spirit or mana regen; orange, purple and green count as both colors. Matching every socket turns on the item''s socket bonus, and a meta gem works only if you meet its color requirement.', 'gems,gem,sockets,socket,gemming,meta gem,socket bonus,cardinal ruby,kings amber,majestic zircon,red gem,yellow gem,blue gem,prismatic', 'items,gems,jewelcrafting,optimization');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_consumables', 'Consumable Items', 'You can have one battle elixir and one guardian elixir active, or a flask, which counts as both and lasts an hour through death. Only one potion can be drunk per fight, such as a Runic Healing or Runic Mana Potion at 80, and a Well Fed food buff stacks with all of it.', 'consumables,consumable,potion,potions,pots,elixir,elixirs,flask,flasks,food buff,well fed,runic healing potion,runic mana potion', 'items,consumables,buffs,performance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_trade_goods', 'Trade Goods and Materials', 'Trade goods are crafting materials: cloth drops from humanoids (Frostweave in Northrend), leather comes from skinning beasts (Borean Leather), ore from mining (Cobalt, Saronite, Titanium) and herbs from herbalism. Eternals and Frozen Orbs go into high-end crafts. Gatherers make steady gold selling them on the auction house.', 'trade goods,materials,mats,crafting materials,frostweave,frostweave cloth,borean leather,eternals,eternal,frozen orb,make gold', 'items,materials,trading,economy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_keys', 'Dungeon and Raid Keys', 'Northrend heroic dungeons need no key, only the level cap. Older keys in use include the Crescent Key from Dire Maul, which opens its locked doors, and the Shadowforge Key for the Shadowforge City gate in Blackrock Depths; rogues can pick many of these locks instead.', 'key,keys,attunement,attuned,crescent key,shadowforge key,heroic key,dungeon key', 'items,keys,access,attunement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_containers', 'Special Containers', 'Locked boxes such as the Froststeel Lockbox drop from Northrend monsters and open with a rogue''s Pick Lock or a blacksmith''s skeleton key (the Titanium Skeleton Key is the highest). Rogues also pickpocket junkboxes from humanoids.', 'lockbox,lockboxes,locked box,junkbox,pick lock,lockpicking,skeleton key,titanium skeleton key,froststeel lockbox', 'items,containers,loot,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_tabards', 'Guild and Faction Tabards', 'Tabards are cosmetic chest-overs. A guild designs its tabard at a guild tabard vendor, and members wear it to show the emblem. Faction tabards are sold by quartermasters; in Northrend the Argent Crusade, Kirin Tor, Knights of the Ebon Blade and Wyrmrest Accord tabards also send dungeon reputation to their faction at level 80.', 'tabard,tabards,guild tabard,faction tabard', 'items,cosmetic,guild,faction');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_quest_rewards', 'Quest Reward Items', 'Many quests let you choose one reward from a list; pick the piece for your armor type and spec, since the rest only sells to a vendor. Famous quest rewards include Quel''Serrar from a Dire Maul chain and, in Wrath, Quel''Delar, a level-80 sword chain started by the Battered Hilt that drops in the Frozen Halls dungeons.', 'quest reward,quest rewards,quel delar,queldelar,battered hilt,quel serrar,quelserrar', 'items,quests,lore,story');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_cosmetic', 'Cosmetic Items', 'There is no wardrobe or appearance-change system yet -- an item''s look is simply whatever is equipped, so cosmetic collecting mostly means non-combat companion pets, which follow a player around and do nothing else. Pets are earned from vendors, quest rewards, holiday events, and rare drops, and many players collect them purely for their own sake. Some weapon enchants add a visual glow or proc animation as a side effect of their stat bonus, which is the closest thing to a customizable weapon appearance available this expansion. Holiday events also hand out costume items, like Hallow''s End''s wand that temporarily transforms the user into a ghost, ninja, pirate, skeleton, or leper gnome.', 'cosmetic,companion pet,companion pets,vanity pet,vanity pets,minipet,minipets,costume,transmog,transmogrification,appearance', 'items,cosmetic,appearance,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_relics', 'Relics and Artifacts', 'Paladins, druids, shamans and death knights carry a relic in the ranged slot instead of a ranged weapon: librams for paladins, idols for druids, totems for shamans and sigils for death knights. Each boosts specific class spells, so the right one depends on spec.', 'relic,relics,libram,librams,idol,idols,sigil,sigils,totem relic', 'items,relics,class,bonuses');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_reputation', 'Reputation System', 'Reputation levels run Hated, Hostile, Unfriendly, Neutral, Friendly, Honored, Revered, Exalted. From Neutral it takes 3,000 points to Friendly, 6,000 to Honored, 12,000 to Revered and 21,000 to Exalted, 42,000 in all. Each faction''s quartermaster sells more as you climb, and humans gain 10% extra reputation.', 'reputation,rep,exalted,revered,standing,faction standing', 'mechanic,reputation,factions,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_auction_house', 'Auction House', 'Every faction capital has an Auction House, such as Stormwind''s Trade District and Orgrimmar''s Valley of Strength, and Booty Bay, Gadgetzan and Everlook have neutral ones shared by both factions; Dalaran and Shattrath have none. Auctions last 12, 24 or 48 hours, the deposit is lost if the item doesn''t sell, and the house keeps 5% of a sale (15% at a neutral house).', 'auction house,ah,auction,auctions,auctioneer,buyout,neutral ah', 'mechanic,economy,trading,market');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_quests', 'Quest System', 'Quest givers show a yellow ! when they have a quest and a yellow ? when you can turn one in. A quest''s level shows as a color: grey is too low to give much experience, green is easy, yellow is your level, orange is hard and red is well above you. The log holds 25 quests, and most can be shared with your party.', 'quest,quests,quest giver,quest log,turn in', 'mechanic,progression,story,objectives');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_talents', 'Talent System', 'Characters get one talent point per level from level 10, 71 by level 80, spent across their class''s three trees. A class trainer resets talents for gold: 1 gold the first time, rising with each respec to a 50 gold cap and dropping back over time. Dual specialization at 40 lets you keep two builds.', 'talents,talent,talent points,talent tree,talent build,respec,reset talents', 'mechanic,character,specialization,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_glyphs', 'Glyph System', 'Each character has three major and three minor glyph slots: one of each opens at level 15, another major at 30 and 80, and another minor at 50 and 70. Glyphs are made by scribes with Inscription and sold on the auction house, and putting a new glyph in a slot destroys the old one.', 'glyph,glyphs,major glyph,minor glyph,glyph slot,glyph slots', 'mechanic,customization,spells,inscription');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_achievements', 'Achievement System', 'Press Y to open achievements; they belong to each character and award points, and some give titles, pets or mounts. For example World Explorer gives the title the Explorer, and Higher Learning, reading the books hidden in Dalaran, gives the Kirin Tor Familiar pet. Feats of Strength give no points.', 'achievement,achievements,achievement points,cheevo,cheevos,feat of strength,achievement title,world explorer,higher learning', 'mechanic,goals,rewards,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_pvp', 'Player vs Player Combat', 'Players fight each other in battlegrounds, arenas, Wintergrasp and the open world. Killing enemy players who give honor and winning objectives earns Honor points, spent with PvP vendors on gear. On a PvP realm contested zones flag you automatically; on a PvE realm you flag yourself with /pvp.', 'pvp,player vs player,honorable kill,hk,pvp combat', 'mechanic,combat,pvp,battlegrounds');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_mounts', 'Mount System', 'Riding is trained in steps: Apprentice (60% ground mounts) at level 20 for 4 gold, Journeyman (100% epic ground) at 40 for 50 gold, Expert (flying) at 60 for 250 gold, Artisan (epic flying) at 70 for 5,000 gold, and Cold Weather Flying, needed to fly in Northrend, at 77 for 1,000 gold. Mounts are bought separately from mount vendors.', 'mount,mounts,riding,riding skill,riding trainer,apprentice riding,journeyman riding,expert riding,artisan riding,epic mount,flying,flying mount,learn to fly', 'mechanic,travel,collection,mounts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_pets', 'Pet System', 'Hunters learn Tame Beast at level 10 and keep beasts as permanent combat pets; Beast Mastery hunters can also tame exotic beasts. Warlocks summon demons, Death Knights raise a ghoul and frost mages get a Water Elemental. Non-combat companion pets are purely cosmetic followers. Stable masters hold the beasts a hunter isn''t using.', 'pet,pets,hunter pet,tame,tame beast,demon pet,warlock pet', 'mechanic,companions,pets,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_guilds', 'Guild System', 'To found a guild, buy a guild charter from a guild master in a capital and collect signatures from other players, then turn it in. The guild leader sets ranks and what each rank may do, including which guild bank tabs it can withdraw from. Guilds in Wrath have no levels or perks.', 'guild charter,create a guild,start a guild,guild ranks,guild leader,guild master,guild invite,guild permissions,make a guild', 'mechanic,social,guilds,community');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_instances', 'Instance System', 'Dungeons are five-player and Wrath raids are 10 or 25. Heroic dungeon lockouts reset daily and raid lockouts weekly; a normal dungeon can be reset from your portrait menu, but you can enter at most five instances per hour.', 'instance,instances,lockout,raid lockout,raid id,instance reset,reset instance,too many instances,saved to', 'mechanic,instances,group_content,difficulty');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_world_events', 'World Events', 'Yearly holidays, all on the in-game calendar: Lunar Festival (Feb 1-14), Love is in the Air (Feb 10-23), Children''s Week (Apr 30-May 6), Midsummer Fire Festival (Jun 21-Jul 4), Brewfest (Sep 20-Oct 4), Hallow''s End (Oct 18-31), Pilgrim''s Bounty (Nov 21-27) and the Feast of Winter Veil (Dec 15-Jan 2).', 'world event,world events,holiday,holidays,seasonal event,calendar,event calendar', 'mechanic,events,world,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_profession_specializations', 'Profession Specializations', 'Several crafts have a specialization with its own recipes: Blacksmithing has Armorsmith and Weaponsmith (then Axe, Mace or Sword), Leatherworking has Dragonscale, Elemental and Tribal, Tailoring has Mooncloth, Shadoweave and Spellfire, Engineering has Goblin and Gnomish, and Alchemy has Elixir, Potion and Transmutation Master.', 'profession specialization,armorsmith,weaponsmith,goblin engineering,gnomish engineering,transmute master,elixir master,potion master,mooncloth,shadoweave,spellfire,dragonscale,tribal leatherworking,elemental leatherworking', 'mechanic,professions,specializations,crafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_currency', 'Currency Systems', 'Besides gold, the currency tab tracks Honor and Arena Points for PvP gear, Emblems of Triumph and Frost for PvE gear, Stone Keeper''s Shards from Wintergrasp for its vendors and heirlooms, and Champion''s Seals from the Argent Tournament dailies. Honor caps at 75,000.', 'currency,currencies,badge,badges,stone keepers shard,stone keepers shards,champions seal,champions seals,arena points', 'mechanic,currency,gearing,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_dungeon_finder', 'Dungeon Finder', 'The Dungeon Finder (patch 3.3, December 2009), open from level 15, automatically groups players across realms for a chosen dungeon or a random one, through a queue where each player selects the Tank, Healer, and/or Damage role they''ll fill. Once a group forms, everyone is teleported directly to the dungeon entrance, and abandoning the run before the group agrees to disband applies the Dungeon Deserter debuff. Queuing for a random Northrend heroic is the most common use: the first one completed each day awards 2 Emblems of Frost, and every additional one that day awards 2 Emblems of Triumph instead, making it the fastest way to gear up at level 80.', 'dungeon finder,lfd,rdf,random dungeon,random heroic,lfg tool,deserter,dungeon queue,daily random', 'mechanic,wotlk,dungeons,grouping');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_heroic_emblems', 'Heroic Dungeons and Emblems', 'Heroic difficulty unlocks at level 80 for every Northrend five-man dungeon, with no attunement or key required as there was in the Burning Crusade -- just queue for it. Heroics and raids pay Emblems rather than gold-bought tokens; by patch 3.3.5 the two currencies actually being earned are Emblem of Triumph (heroics, Trial of the Crusader, and repeat random-dungeon wins) and Emblem of Frost (Icecrown Citadel and the day''s first random heroic). The earlier Emblem of Heroism, Valor, and Conquest from Naxxramas, Ulduar, and Trial of the Crusader''s launch are no longer dropped, having been superseded as raid content advanced. Emblems are spent with quartermasters in Dalaran and Icecrown for current-tier epic gear.', 'heroic,heroics,heroic dungeon,heroic dungeons,emblem,emblems,emblem of triumph,emblem of frost,frost emblems,triumph emblems,emblem vendor', 'mechanic,wotlk,dungeons,currency,gearing');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_dual_spec', 'Dual Talent Specialization', 'Dual talent specialization (patch 3.1) lets a character save two separate talent builds -- each with its own glyphs and action bars -- and swap between them outside combat. It costs 1000 gold, requires level 40, and is bought once from your class trainer; after that, switching between the two saved specs is free and unlimited. Players commonly keep one PvE spec and one PvP spec, or a tank/healer spec alongside a damage spec, and swap depending on what the group needs.', 'dual specialization,dual talent specialization,dualspec,dual talent', 'mechanic,wotlk,talents,character');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_cold_weather_flying', 'Cold Weather Flying', 'Cold Weather Flying is the extra skill needed to use a flying mount in Northrend; Flying itself is learned at 60 with Expert riding, but Expert or Artisan alone isn''t enough there. It''s trained from a flying trainer in Dalaran or the Storm Peaks for 1,000 gold at level 77. A level 80 can buy the Tome of Cold Weather Flight for 1,000 gold and mail it to an alt, letting that alt fly in Northrend from 68.', 'cold weather flying,cwf,fly in northrend,flying in northrend,tome of cold weather flight', 'mechanic,wotlk,flying,mounts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_death_knight_runes', 'Death Knight Runes and Runic Power', 'Death Knights don''t use mana, rage or energy: they have six runes, two Blood, two Frost and two Unholy, plus a Runic Power bar. Spending a rune casts its ability and puts that rune on a short recharge, and spending runes builds the Runic Power that fuels abilities like Death Coil. As Wrath''s hero class, every Death Knight starts at level 55.', 'runes,rune,runic power,blood rune,frost rune,unholy rune,death rune,hero class,dk runes', 'mechanic,wotlk,class,death knight,resource');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_vehicle_combat', 'Vehicle Combat', 'Vehicles are a Wrath of the Lich King addition: mountable siege engines, cannons, and creatures that swap a player''s normal action bars for the vehicle''s own abilities for as long as they''re in the seat. They show up throughout the expansion -- Ulduar''s Flame Leviathan fight, the cannons defending Wintergrasp and Isle of Conquest, the siege engines and demolishers of Strand of the Ancients, and mine-cart or turret sections tucked into several dungeons. Leaving a vehicle returns a player to their normal spellbook immediately, and most vehicles can be destroyed out from under their rider by enemy fire.', 'vehicle,vehicles,vehicle combat,siege engine,demolisher', 'mechanic,wotlk,vehicles,pvp,raiding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_world_bosses', 'World Bosses', 'World bosses spawn in the open world and anyone can attack them: Doom Lord Kazzak roams Hellfire Peninsula, Doomwalker walks Shadowmoon Valley, and Azuregos, a blue dragon, guards Azshara. They need a raid-sized group and respawn on long timers.', 'world boss,world bosses,kazzak,doom lord kazzak,azuregos,doomwalker', 'npcs,bosses,world,loot');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_rare_elites', 'Rare Elite Creatures', 'Rare monsters show a silver dragon on their portrait and spawn rarely at fixed spots; elites have a gold dragon and need a group. Killing every Northrend rare earns the Frostbitten achievement, and the most hunted is the Time-Lost Proto-Drake in the Storm Peaks, which drops its own mount.', 'rare,rares,rare elite,rare spawn,elite,elites,silver dragon,frostbitten,time lost proto drake,tlpd', 'npcs,rare,elite,achievements');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_class_trainers', 'Class and Profession Trainers', 'Class trainers stand in the capitals and in each starting zone''s main town, and teach new spells and ranks for gold, with new ones every two levels. Profession trainers are in the capitals too, and the Grand Master ranks for Northrend (skill 350 to 450) are taught in Dalaran. Class trainers also reset talents and sell dual spec at 40.', 'trainer,trainers,class trainer,profession trainer,training,spell ranks,grand master trainer', 'npcs,training,progression,skills');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_vendors', 'Special Vendors', 'Reputation quartermasters sell recipes, enchants and gear as your standing rises: the Kirin Tor''s is Archmage Alvareaux in Dalaran, the Sons of Hodir''s is Lillehoff at Dun Niffelem in the Storm Peaks, and the Wyrmrest Accord''s is Cielstrasza at Wyrmrest Temple in Dragonblight.', 'quartermaster,quartermasters,rep vendor,reputation vendor,faction vendor,special vendor,kirin tor quartermaster', 'npcs,vendors,items,reputation');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_flight_masters', 'Flight Masters', 'Speak to a flight master once to learn that flight path; after that you can fly between any paths you know for a fee that grows with distance. Alliance ride gryphons and hippogryphs, Horde ride wyverns, bats and dragonhawks, and Northrend''s flight masters serve both factions in places like Dalaran.', 'flight master,flight masters,flight path,flight paths,fp,gryphon,wyvern,taxi', 'npcs,travel,flight,exploration');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_innkeepers', 'Innkeepers and Hearthstones', 'Speak to any innkeeper and make the inn your home to bind your Hearthstone there; the Hearthstone then brings you back to that inn on a 30-minute cooldown. Logging out in an inn or a capital builds rested experience, and innkeepers also sell food and drink.', 'innkeeper,inn,hearthstone,hearth,hs,set hearth,set my hearth,bind hearth', 'npcs,travel,rest,hearthstone');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_banker', 'Bankers and Guild Banks', 'Bankers in every capital and in Dalaran hold your personal bank: 28 slots plus seven bag slots bought with gold. A guild bank, opened at a guild vault, has up to six tabs of 98 slots, bought with gold, and the guild leader sets who can withdraw from each.', 'bank,banker,bank slots,bank bag,bank space,guild bank,gbank,guild vault', 'npcs,storage,guild,inventory');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_stable_masters', 'Stable Masters', 'Stable masters hold a hunter''s tamed beasts, letting one hunter keep several pets and swap between them. They do nothing for mounts, which live in the spellbook once learned. Stables are found in most towns and every capital. Swapping at a stable is how a hunter changes to a pet better suited to the fight ahead.', 'stable master,stable,stabled pet,swap pet,stable slot,stable slots', 'npcs,mounts,pets,storage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_lore_figures', 'Important Lore Figures', 'Wrath''s story centers on Arthas Menethil, the Lich King, waiting on the Frozen Throne atop Icecrown Citadel. Along the way players face Malygos, the blue Dragon Aspect, in the Eye of Eternity and the Old God Yogg-Saron beneath Ulduar, while Tirion Fordring leads the Argent Crusade and Darion Mograine the Knights of the Ebon Blade.', 'lore,lich king lore,arthas,tirion fordring,darion mograine,malygos lore,yogg saron lore', 'npcs,lore,story,characters');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_faction_leaders', 'Faction Leaders', 'Alliance leaders: King Varian Wrynn in Stormwind, King Magni Bronzebeard in Ironforge, High Tinker Mekkatorque for the gnomes, Tyrande Whisperwind in Darnassus and Prophet Velen in the Exodar. Horde leaders: Warchief Thrall in Orgrimmar, Cairne Bloodhoof in Thunder Bluff, Sylvanas Windrunner in the Undercity, Lor''themar Theron in Silvermoon and Vol''jin of the Darkspear trolls.', 'faction leader,faction leaders,who leads,who rules,mekkatorque,voljin,lorthemar,lor themar,cairne,varian', 'npcs,factions,leaders,politics');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_merchants', 'Specialized Merchants', 'General goods vendors sell food, drink and bags, and reagent vendors carry class reagents. Rogues buy poisons from poison vendors and hunters buy arrows and bullets from ammo vendors. Armorers and weaponsmiths repair your gear, and any vendor buys your loot.', 'reagent vendor,reagents,poison vendor,poisons,ammo,ammo vendor,arrows,bullets,repair,repairs,general goods', 'npcs,merchants,goods,supplies');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_guards', 'City Guards and Sentries', 'Guards in capitals and towns attack enemy-faction players who are flagged and hostile creatures that wander in. Ask any guard for directions and it marks the nearest bank, inn, trainer, flight master or auction house on your minimap.', 'guard,guards,city guard,ask a guard,directions', 'npcs,guards,security,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_transport', 'Transportation NPCs', 'Boats and zeppelins are free. To Northrend, Alliance sail from Stormwind Harbor to Valiance Keep in Borean Tundra or from Menethil Harbor to Valgarde in Howling Fjord; Horde fly from Orgrimmar to Warsong Hold or from the Undercity to Vengeance Landing. The neutral Booty Bay-Ratchet boat links the old continents, and Shattrath has portals to your faction''s capitals.', 'boat,boats,zeppelin,zeppelins,zep,get to northrend,go to northrend,transport,transportation', 'npcs,transport,travel,convenience');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_alchemy', 'Alchemy Profession', 'Alchemists turn herbs into potions, elixirs and flasks, so the profession pairs with Herbalism. Its Mixology perk makes the flasks and elixirs an alchemist knows stronger and longer-lasting on them, and transmutes turn materials into rarer ones, such as Titanium. Grand Master alchemy is taught in Dalaran.', 'alchemy,alchemist,alch,transmute,transmutes,transmutation,mixology', 'profession,crafting,consumables,raiding,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_blacksmithing', 'Blacksmithing Profession', 'Blacksmiths make plate and mail armor, weapons and the Eternal Belt Buckle from bars smelted out of ore, so it pairs with Mining. Trainers are in most capitals, the Grand Master rank (skill 350 to 450) is taught in Dalaran, and at 400 skill a blacksmith can add a socket to their own bracers and gloves.', 'blacksmithing,blacksmith,smithing,socket bracer,socket gloves,plate crafting', 'profession,crafting,weapons,armor,raiding,warrior,paladin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_enchanting', 'Enchanting Profession', 'Enchanters disenchant green and better items into dusts, essences and shards (Infinite Dust, Greater Cosmic Essence and Dream Shards in Northrend, Abyss Crystals from epics) and use them to enchant gear. It needs no gathering profession, and its perk is enchanting your own rings.', 'enchanting,enchanter,disenchant,disenchanting,dust,infinite dust,dream shard,abyss crystal,cosmic essence,ring enchant,ench', 'profession,crafting,enhancements,auction house,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_engineering', 'Engineering Profession', 'Engineers build guns, scopes, explosives and gadgets from mined metal, so it pairs with Mining. Their perk is tinkers only engineers can use, like Hyperspeed Accelerators on gloves and Nitro Boosts on boots, plus the Wormhole Generator: Northrend and the Mekgineer''s Chopper or Mechano-Hog motorcycle.', 'engineering,engineer,engi,hyperspeed accelerators,nitro boosts,wormhole,wormhole generator,mechano hog,mekgineers chopper,scope,scopes', 'profession,crafting,devices,specialized,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_herbalism', 'Herbalism Profession', 'Herbalists gather herbs for Alchemy and Inscription, with Find Herbs showing nodes on the minimap. Northrend herbs include Goldclover, Tiger Lily, Adder''s Tongue, Lichbloom, Icethorn and the rare Frost Lotus. The perk Lifeblood is a self-heal.', 'herbalism,herbalist,herb,herbs,herbing,frost lotus,lichbloom,icethorn,adders tongue,goldclover,lifeblood,find herbs,peacebloom,silverleaf', 'profession,gathering,materials,alchemy,inscription');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_inscription', 'Inscription Profession', 'Scribes mill herbs, five at a time, into pigments, turn those into inks, and make glyphs, off-hand books, Darkmoon Cards and vellums. Their perk is Master''s Inscription shoulder enchants for themselves, and Grand Master Inscription is taught in Dalaran.', 'inscription,scribe,scribes,milling,mill herbs,pigment,pigments,ink,inks,darkmoon card,darkmoon cards,vellum', 'profession,crafting,spell mods,cosmetic,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_jewelcrafting', 'Jewelcrafting Profession', 'Jewelcrafters prospect ore, five at a time, for raw gems, cut them, and make rings, necklaces and trinkets, so it pairs with Mining. Their perk is Dragon''s Eye gems only they can socket, up to three. Timothy Jones in Dalaran gives a daily quest paying tokens for new designs.', 'jewelcrafting,jewelcrafter,jc,prospect,prospecting,dragons eye,dragons eyes,cut gems', 'profession,crafting,jewelry,sockets,valuable,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_leatherworking', 'Leatherworking Profession', 'Leatherworkers make leather and mail armor, armor kits, leg armors like Icescale Leg Armor, and drums from skinned leather, so it pairs with Skinning. Their perk is Fur Lining bracer enchants for themselves.', 'leatherworking,leatherworker,lw,fur lining,leg armor,armor kit,drums', 'profession,crafting,armor,bags,leather classes,druid,rogue,hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_mining', 'Mining Profession', 'Miners gather ore and stone from mineral nodes, shown on the minimap with Find Minerals, and smelt it into bars at a forge for Blacksmithing, Engineering and Jewelcrafting. Northrend ores are Cobalt, Saronite and the rare Titanium, and the perk Toughness adds stamina.', 'mining,miner,ore,ores,smelting,smelt,cobalt,saronite,titanium,toughness,find minerals,mining node', 'profession,gathering,materials,crafting,blacksmithing,engineering,jewelcrafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_skinning', 'Skinning Profession', 'Skinners skin dead beasts, and some dragonkin, for leather and hides used in Leatherworking; humanoids drop cloth instead. Northrend gives Borean Leather and the rare Arctic Fur, and the perk Master of Anatomy adds critical strike rating.', 'skinning,skinner,hides,borean leather,arctic fur,master of anatomy', 'profession,gathering,materials,leatherworking');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_tailoring', 'Tailoring Profession', 'Tailors sew cloth gear and bags from cloth looted off humanoids, like Frostweave Cloth in Northrend, and need no gathering profession. Their perk is cloak embroideries only they can use, Lightweave, Darkglow and Swordguard, and they make Moonshroud, Ebonweave and Spellweave cloth on a cooldown.', 'tailoring,tailor,frostweave bag,embroidery,lightweave,darkglow,swordguard,moonshroud,ebonweave,spellweave', 'profession,crafting,armor,bags,cloth classes,mage,priest,warlock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_cooking', 'Cooking Profession', 'Cooking is a secondary profession anyone can learn alongside two primaries. Food gives Well Fed buffs, and the Fish Feast feeds a whole raid. Dozens of Northrend recipes are bought with Dalaran Cooking Awards from the cooking dailies of Katherine Lee or Awilo Lon''gomba in Dalaran.', 'cooking,cook,fish feast,cooking recipe,cooking recipes,dalaran cooking award', 'profession,secondary,consumables,buffs,raiding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_fishing', 'Fishing Profession', 'Learn Fishing from a fishing trainer, buy a Fishing Pole, and cast in any open water; lures like Nightcrawlers add skill for ten minutes. Marcia Chase in Dalaran gives a daily fishing quest, and Stranglethorn Vale''s Fishing Extravaganza runs on Sundays.', 'fishing,fish,fishing pole,lure,lures,fishing skill,fishing trainer,fishing extravaganza,kaluak fishing derby,nightcrawlers', 'profession,secondary,gathering,materials,consumables');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_first_aid', 'First Aid Profession', 'First Aid is a secondary profession every character can learn, used to make bandages from cloth that heal over a short channel. Damage interrupts a bandage, and Recently Bandaged blocks another for a minute. The best one, Dense Frostweave Bandage, is learned from a manual at 450 skill.', 'first aid,bandage,bandages,recently bandaged,frostweave bandage', 'profession,secondary,consumables,healing,solo');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mage_professions_guide', 'Best Professions for Mages', 'For mages the useful perks are Tailoring''s Lightweave Embroidery, a spell power proc on the cloak, and Enchanting''s ring enchants, and Tailoring makes cloth gear a mage can wear. Jewelcrafting''s Dragon''s Eyes are another option.', 'mage professions,professions for mage,best professions for mage,mage crafting,mage tradeskills,mage profession perks', 'profession,mage,cloth classes,spellcaster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('warrior_professions_guide', 'Best Professions for Warriors', 'For warriors, Blacksmithing adds sockets to bracers and gloves and makes plate, Jewelcrafting gives Dragon''s Eyes, and Mining''s Toughness adds stamina for tanks. Engineering''s Hyperspeed Accelerators suit DPS warriors.', 'warrior professions,professions for warrior,best professions for warrior,warrior crafting,warrior tradeskills,warrior profession perks', 'profession,warrior,plate classes,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('paladin_professions_guide', 'Best Professions for Paladins', 'For paladins, Blacksmithing adds sockets to bracers and gloves and makes plate, and Jewelcrafting gives Dragon''s Eyes; holy paladins often add Enchanting for ring enchants or Inscription for shoulder inscriptions.', 'paladin professions,professions for paladin,best professions for paladin,paladin crafting,paladin tradeskills,paladin profession perks', 'profession,paladin,plate classes,healer,tank');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('hunter_professions_guide', 'Best Professions for Hunters', 'For hunters, Engineering makes guns and scopes and gives Hyperspeed Accelerators, Leatherworking makes mail and Fur Lining, and Jewelcrafting gives Dragon''s Eyes. Skinning pairs with Leatherworking.', 'hunter professions,professions for hunter,best professions for hunter,hunter crafting,hunter tradeskills,hunter profession perks', 'profession,hunter,leather classes,ranged');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('rogue_professions_guide', 'Best Professions for Rogues', 'For rogues, Leatherworking makes leather gear and gives Fur Lining, Engineering adds Hyperspeed Accelerators and gadgets, and Jewelcrafting gives Dragon''s Eyes. Rogues open lockboxes themselves, so they need no key-making profession.', 'rogue professions,professions for rogue,best professions for rogue,rogue crafting,rogue tradeskills,rogue profession perks', 'profession,rogue,leather classes,melee,stealth');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('priest_professions_guide', 'Best Professions for Priests', 'For priests, Tailoring makes cloth gear and gives Lightweave Embroidery, Enchanting gives ring enchants, and Inscription gives shoulder inscriptions and glyphs. Jewelcrafting gives Dragon''s Eyes.', 'priest professions,professions for priest,best professions for priest,priest crafting,priest tradeskills,priest profession perks', 'profession,priest,cloth classes,healer,caster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('shaman_professions_guide', 'Best Professions for Shamans', 'For shamans, Leatherworking makes mail and gives Fur Lining, Jewelcrafting gives Dragon''s Eyes, and Enchanting gives ring enchants. Skinning or Mining pair with those for materials.', 'shaman professions,professions for shaman,best professions for shaman,shaman crafting,shaman tradeskills,shaman profession perks', 'profession,shaman,leather classes,healer,caster,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('warlock_professions_guide', 'Best Professions for Warlocks', 'For warlocks, Tailoring makes cloth gear and gives Lightweave Embroidery, Enchanting gives ring enchants, and Jewelcrafting gives Dragon''s Eyes. Soulstones and healthstones are warlock spells, not crafts.', 'warlock professions,professions for warlock,best professions for warlock,warlock crafting,warlock tradeskills,warlock profession perks', 'profession,warlock,cloth classes,caster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('druid_professions_guide', 'Best Professions for Druids', 'For druids, Leatherworking makes leather gear and gives Fur Lining, Jewelcrafting gives Dragon''s Eyes, and Enchanting gives ring enchants. Herbalism also heals with Lifeblood.', 'druid professions,professions for druid,best professions for druid,druid crafting,druid tradeskills,druid profession perks', 'profession,druid,leather classes,healer,caster,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_overview', 'Professions', 'Every character can learn two primary professions and all three secondary ones: Cooking, Fishing and First Aid. Gathering professions are Herbalism, Mining and Skinning; crafting ones are Alchemy, Blacksmithing, Enchanting, Engineering, Inscription, Jewelcrafting, Leatherworking and Tailoring. Skill ranks cap at 75, 150, 225, 300, 375 and 450, the last taught by Grand Master trainers in Dalaran.', 'profession,professions,prof,profs,primary profession,secondary profession', 'profession,overview');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_battlegrounds', 'Battlegrounds', '3.3.5 has six battlegrounds: Warsong Gulch (capture the flag, from level 10), Arathi Basin (five nodes, from 20), Alterac Valley (40 a side, from 51), Eye of the Storm (from 61), and Strand of the Ancients and Isle of Conquest (both from 71). Queue from a Battlemaster or the PvP window. Wintergrasp is a zone, not a battleground.', 'battleground,battlegrounds,bg,bgs,queue for bg,pvp queue', 'pvp,battlegrounds,teamwork,honor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_arenas', 'Arena Combat', 'Arena teams fight 2v2, 3v3 or 5v5 in Nagrand Arena, Blade''s Edge Arena, the Ruins of Lordaeron, the Dalaran sewers and the Ring of Valor. Rated matches move your team rating, and Arena Points are paid out weekly by rating if you played at least 10 games that week; skirmishes are unrated practice.', 'arena,arenas,2v2,3v3,5v5,arena team,arena rating,skirmish,skirmishes,ring of valor,dalaran arena', 'pvp,arena,skill,competition');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_world_pvp', 'World PvP', 'World PvP happens anywhere outside sanctuaries: classic hot spots are Tarren Mill against Southshore in Hillsbrad Foothills and the Gurubashi Arena in Stranglethorn Vale, and Wintergrasp is Northrend''s open-world PvP zone, where the attackers besiege the fortress with siege vehicles on a timer.', 'world pvp,wpvp,tarren mill,southshore,gurubashi arena,open world pvp', 'pvp,world,open_world,rivalries');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_ranks', 'PvP Ranks and Titles', 'The old Vanilla system of 14 numbered PvP ranks was replaced when the honor system was overhauled in the Burning Crusade: honor points are now spent directly on gear instead of being ground through ranks. The prestigious ''Grand Marshal'' (Alliance) and ''High Warlord'' (Horde) titles still exist, but are now awarded to the single highest-rated arena player of each class and faction at the end of a PvP season, alongside seasonal Gladiator titles for the top-rated teams. Titles are prestigious and show PvP dedication.', 'pvp rank,pvp ranks,pvp title,pvp titles,grand marshal,high warlord,gladiator,rank 14,duelist', 'pvp,ranks,titles,prestige');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_gear_progression', 'PvP Gear Progression', 'PvP gear carries resilience, which lowers the chance to be crit and the damage taken from players. Entry pieces are bought with Honor, the season''s best pieces need Arena Points, and the top items also require a personal arena rating. Honor caps at 75,000, so spend it before hitting the cap.', 'pvp gear,honor gear,arena gear,resilience,resil,resi,gladiator gear,pvp set,pvp sets', 'pvp,gear,progression,equipment');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_faction_conflicts', 'Faction Conflicts', 'The faction war flared at the Wrathgate in Dragonblight, where Grand Apothecary Putress unleashed a plague that killed both Bolvar Fordragon and Dranosh Saurfang. Varimathras seized the Undercity at the same time, and Thrall and King Varian Wrynn retook it together in the Battle for the Undercity.', 'wrathgate,battle for the undercity,putress,faction war,alliance vs horde,horde vs alliance', 'pvp,factions,conflicts,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_honor_system', 'Honor System', 'Honor comes from honorable kills, battleground wins and objectives, and Wintergrasp; a player low enough to show grey to you gives none. Honor doesn''t decay and caps at 75,000, and it''s spent with PvP vendors on gear.', 'honor,honor points,honor cap,honor farm,honor system,honorable kills,hks', 'pvp,honor,system,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_ganking', 'Ganking and Ambush Tactics', 'Ganking is a much higher-level player killing a low-level one, common on PvP realms in contested zones like Stranglethorn Vale and Hillsbrad Foothills. It earns the ganker nothing, since a target low enough to show grey gives no honor. The usual answers are calling friends or a guard, or leaving the area.', 'gank,ganking,ganked,ganker,gankers,corpse camping,corpse camped,camping', 'pvp,tactics,ganking,controversy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_objectives', 'Battleground Objectives', 'How each battleground is won: Warsong Gulch, capture the enemy flag three times; Arathi Basin, hold more of the five nodes to win the resource race; Alterac Valley, kill the enemy general, Drek''Thar or Vanndar; Eye of the Storm, hold towers and carry the center flag; Strand of the Ancients, reach the relic faster; Isle of Conquest, break the keep and kill its general.', 'bg objectives,battleground objectives,flag carrier,efc,capture flag,cap a node,nodes', 'pvp,objectives,battlegrounds,strategy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_rewards', 'PvP Rewards and Incentives', 'Beyond gear, PvP pays titles and mounts: each season''s top arena teams earn the Gladiator title and that season''s frost wyrm, the Deadly, Furious, Relentless and Wrathful Gladiator''s Frost Wyrm in Wrath, and the For the Alliance and For the Horde achievements, killing the enemy faction''s leaders, award a Black War Bear.', 'pvp rewards,pvp mount,gladiator mount,frost wyrm,black war bear', 'pvp,rewards,incentives,motivation');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_class_stories', 'Class-Specific Storylines', 'The best-known class storyline is the Death Knight''s: starting at level 55 in Acherus, the Ebon Hold, death knights serve the Lich King in the Scarlet Enclave of the Eastern Plaguelands, earn the Acherus Deathcharger, and break free at the Battle for Light''s Hope Chapel before being sent to their faction''s capital.', 'class quest,class quests,class storyline,death knight quests,dk starting zone,acherus,ebon hold,scarlet enclave', 'quests,story,class,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_zone_storylines', 'Zone Story Arcs', 'Each Northrend zone follows its own story: the vrykul of Utgarde in Howling Fjord, the blue dragonflight and the Nexus in Borean Tundra, the Wrathgate in Dragonblight, the Drakkari trolls'' dying gods in Zul''Drak, Thorim and the secrets of Ulduar in the Storm Peaks, and the war on the Lich King''s doorstep in Icecrown.', 'zone story,zone storyline,zone storylines,storyline,storylines,story quests', 'quests,story,zones,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_reputation_grinds', 'Reputation Quest Hubs', 'Northrend''s reputation dailies: the Argent Tournament in Icecrown, the Sons of Hodir at Dun Niffelem in the Storm Peaks, the Kalu''ak at their fishing villages, and in Sholazar Basin either the Oracles or the Frenzyheart, since siding with one turns the other hostile.', 'rep dailies,reputation dailies,reputation quests,daily hub,kaluak,argent tournament dailies', 'quests,reputation,grinding,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_dungeon_quests', 'Dungeon and Raid Quests', 'Dungeons usually have quests from NPCs at or just inside the entrance, so check before zoning in. In Dalaran, Archmage Lan''dalock gives the weekly raid quest to kill a named boss, such as Patchwerk Must Die! or Lord Marrowgar Must Die!, for extra Emblems.', 'dungeon quest,dungeon quests,landalock,lan dalock', 'quests,dungeons,raids,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_epic_questlines', 'Epic Quest Chains', 'A quest chain is a series where each quest unlocks the next. Wrath''s long ones include the Wrathgate and the Battle for the Undercity, the Sons of Hodir chain in the Storm Peaks, Quel''Delar from the Battered Hilt, and Shadowmourne for Icecrown Citadel raiders.', 'quest chain,quest chains,questline,questlines,epic quest,chain quest,long quest', 'quests,epic,storylines,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_profession_quests', 'Profession Quest Lines', 'Dalaran has the Northrend profession dailies: the Grand Master cooking trainers, Katherine Lee for the Alliance and Awilo Lon''gomba for the Horde, give cooking dailies paying Dalaran Cooking Awards; Marcia Chase gives a fishing daily; and Timothy Jones gives a jewelcrafting daily paying Dalaran Jewelcrafter''s Tokens.', 'profession quest,profession quests,profession dailies,cooking daily,cooking dailies,fishing daily,jewelcrafting daily,jc daily,dalaran cooking award,jewelcrafters token', 'quests,professions,lore,recipes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_escort_quests', 'Escort and Protection Quests', 'In an escort quest the NPC walks a fixed route and fights beside you; if it dies the quest fails, and you abandon it and take it again once the NPC is back. Party members on the same quest who stay nearby all get credit.', 'escort,escort quest,escort quests,escorting', 'quests,escort,protection,challenging');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_group_quests', 'Group and Raid Quests', 'Quests tagged Group in the log suggest a party size because their targets are elites, which show a gold dragon on their portrait. While you''re in a raid group, ordinary quest kills and items don''t count, only quests tagged Raid do, so convert back to a party to finish quests.', 'group quest,group quests,elite quest,raid quest,raid quests,quest in raid,party quest', 'quests,group,raid,coordination');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_repeatable_quests', 'Repeatable and Daily Quests', 'Daily quests can be done once per day and reset at the realm''s daily reset; you can finish up to 25 of them a day. Big Northrend daily hubs are the Argent Tournament, the Sons of Hodir and Wyrmrest Temple, plus the Dalaran cooking and fishing dailies. Some quests, like the raid weekly, reset once a week.', 'daily,dailies,daily quest,daily quests,repeatable,repeatable quest,daily reset,weekly quest,how many dailies', 'quests,repeatable,daily,grinding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_arms_warrior', 'Arms Warrior', 'Arms is the two-handed warrior tree, built around Mortal Strike and the healing debuff it leaves. Overpower punishes a target that dodges and Rend bleeds it, while Sweeping Strikes spreads damage across a pack. Bladestorm is the deep talent: a channelled spin that hits everything nearby and cannot be interrupted by most crowd control.', 'arms warrior,mortal strike,bladestorm,sweeping strikes,overpower,two handed warrior', 'spec,warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_fury_warrior', 'Fury Warrior', 'Fury dual-wields and runs on Bloodthirst and Whirlwind, spending rage about as fast as it builds. Titan''s Grip is the tree''s signature: it allows two-handed weapons in both hands at a hit penalty. Death Wish and Rampage push damage higher, the first by taking more of it.', 'fury warrior,bloodthirst,titans grip,death wish,rampage,dual wield warrior', 'spec,warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_protection_warrior', 'Protection Warrior', 'Protection is the warrior tanking tree. Shield Slam and Devastate hold threat, and Shockwave stuns everything in a cone ahead of you. Last Stand and Spell Reflection are the survival cooldowns, and Vigilance hands threat back from whoever is pulling too much.', 'protection warrior,prot warrior,warrior tank,shield slam,devastate,shockwave,vigilance,spell reflection', 'spec,warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_holy_paladin', 'Holy Paladin', 'Holy is the paladin healing tree, built on Holy Light and Flash of Light with Holy Shock as the instant. Beacon of Light defines it: heals landed on one target are duplicated onto the beacon, so healing the tank also heals whoever is beaconed. Sacred Shield and Divine Favor fill out the kit, and it runs on mana like every paladin spec.', 'holy paladin,holy pally,paladin healer,beacon of light,holy shock,holy light,flash of light,sacred shield', 'spec,paladin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_protection_paladin', 'Protection Paladin', 'Protection is the paladin tanking tree and the best in the game at holding several targets at once. Avenger''s Shield pulls at range, Hammer of the Righteous strikes three targets, and Holy Shield turns blocked hits into damage. Ardent Defender and Righteous Fury are what keep the plate standing.', 'protection paladin,prot paladin,prot pally,paladin tank,avengers shield,hammer of the righteous,holy shield,ardent defender', 'spec,paladin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_retribution_paladin', 'Retribution Paladin', 'Retribution is the paladin melee damage tree. Crusader Strike and Divine Storm are the core, and Divine Storm hits everything around you while healing part of the group. Seal of Command and Repentance come from this tree too.', 'retribution paladin,ret paladin,ret pally,crusader strike,divine storm,seal of command,repentance', 'spec,paladin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_beast_mastery_hunter', 'Beast Mastery Hunter', 'Beast Mastery pushes the pet as far as it will go: extra pet talent points, exotic pets no other tree can tame, and Bestial Wrath as a burst window. The Beast Within extends that window to the hunter as well. Kill Command and Intimidation come from here, and it is the easiest hunter tree to level alone with.', 'beast mastery,bm hunter,beast mastery hunter,bestial wrath,kill command,the beast within,exotic pet,pet hunter', 'spec,hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_marksmanship_hunter', 'Marksmanship Hunter', 'Marksmanship is the ranged damage tree, built on Aimed Shot and Chimera Shot. Trueshot Aura raises the group''s attack power, Silencing Shot interrupts casters, and Readiness resets the hunter''s shot cooldowns outright. It leans on the hunter rather than the pet.', 'marksmanship hunter,mm hunter,marksman hunter,aimed shot,chimera shot,silencing shot,trueshot aura,readiness', 'spec,hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_survival_hunter', 'Survival Hunter', 'Survival is the traps-and-fire tree. Explosive Shot is its core attack and Lock and Load refunds it from traps and periodic damage. Black Arrow and Wyvern Sting come from here, and the tree raises the whole group''s melee critical strike chance.', 'survival hunter,sv hunter,explosive shot,lock and load,black arrow,wyvern sting', 'spec,hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_assassination_rogue', 'Assassination Rogue', 'Assassination is the poison and dagger tree, built on Mutilate, which strikes with both weapons at once and requires daggers. Envenom spends combo points as poison damage, Hunger For Blood ramps it up, and Cold Blood guarantees a critical strike. It is at its best on a single target.', 'assassination rogue,mutilate rogue,mutilate,envenom,cold blood,hunger for blood,poison rogue,dagger rogue', 'spec,rogue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_combat_rogue', 'Combat Rogue', 'Combat is the steady damage tree and the one indifferent to which weapons you carry. Sinister Strike builds combo points, Blade Flurry adds a second target, and Adrenaline Rush floods energy. Killing Spree is the deep talent: the rogue teleports between nearby targets, swinging at each.', 'combat rogue,sinister strike,blade flurry,adrenaline rush,killing spree', 'spec,rogue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_subtlety_rogue', 'Subtlety Rogue', 'Subtlety is the stealth and burst tree and the strongest rogue tree in PvP. Shadowstep closes from behind, Hemorrhage replaces the standard builder, and Preparation resets the escape cooldowns. Shadow Dance is the deep talent: a window where stealth-only abilities work in the open.', 'subtlety rogue,sub rogue,shadow dance,shadowstep,hemorrhage,premeditation,stealth rogue', 'spec,rogue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_discipline_priest', 'Discipline Priest', 'Discipline heals by preventing damage rather than repairing it: Power Word: Shield absorbs the hit before it lands and Rapture returns mana when the shield breaks. Penance is the tree''s signature, a channelled three-tick heal that can also be aimed at an enemy. Pain Suppression and Power Infusion are the cooldowns that earn it a raid slot.', 'discipline priest,disc priest,penance,power word shield,pain suppression,power infusion,rapture,shield healer', 'spec,priest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_holy_priest', 'Holy Priest', 'Holy is the priest throughput tree, built for keeping several people up at once. Circle of Healing hits a target''s whole party, Prayer of Mending bounces to whoever takes damage next, and Lightwell is the tree''s much-ignored free heal. Guardian Spirit is the emergency button: it prevents one death outright.', 'holy priest,circle of healing,guardian spirit,prayer of mending,lightwell,priest healer', 'spec,priest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_shadow_priest', 'Shadow Priest', 'Shadow is the priest damage tree and it is played entirely in Shadowform. Shadow Word: Pain, Vampiric Touch and Mind Flay keep damage rolling while Mind Blast fills the gaps. Vampiric Embrace and Vampiric Touch feed health and mana back to the group, which is most of why raids bring one. Dispersion is the escape and mana cooldown.', 'shadow priest,shadowform,mind flay,vampiric touch,vampiric embrace,shadow word pain,mind blast,dispersion', 'spec,priest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_blood_death_knight', 'Blood Death Knight', 'Blood is the self-healing death knight tree, and in this expansion it is a damage tree that happens to be very hard to kill. Heart Strike is the core strike, Vampiric Blood and Rune Tap keep it standing, and Dancing Rune Weapon summons a copy of the weapon to fight alongside it. It is the usual choice for levelling alone.', 'blood death knight,blood dk,heart strike,vampiric blood,dancing rune weapon,rune tap', 'spec,death knight');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_frost_death_knight', 'Frost Death Knight', 'Frost is the dual-wield and burst death knight tree. Obliterate and Frost Strike are the core, Howling Blast hits everything around the target, and Killing Machine and Rime make those strikes free or guaranteed to crit. Hungering Cold freezes everything nearby. It also tanks perfectly well.', 'frost death knight,frost dk,obliterate,howling blast,frost strike,killing machine,hungering cold', 'spec,death knight');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_unholy_death_knight', 'Unholy Death Knight', 'Unholy is the disease and pet tree. Scourge Strike scales with the diseases already on the target and Unholy Blight spreads damage around it. Master of Ghouls makes the ghoul a permanent pet rather than a short summon, Summon Gargoyle is the deep cooldown, and Bone Shield keeps the death knight alive while it works.', 'unholy death knight,unholy dk,scourge strike,summon gargoyle,bone shield,unholy blight,permanent ghoul', 'spec,death knight');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_elemental_shaman', 'Elemental Shaman', 'Elemental is the caster shaman tree. Lightning Bolt and Chain Lightning are the filler and Lava Burst is the payoff, since it always critically strikes a target burning from Flame Shock. Thunderstorm knocks everything back and returns mana, and Elemental Mastery guarantees a critical strike. Its totems buff the whole group.', 'elemental shaman,ele shaman,lava burst,chain lightning,thunderstorm,elemental mastery,caster shaman', 'spec,shaman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_enhancement_shaman', 'Enhancement Shaman', 'Enhancement is the melee shaman tree, dual-wielding behind Windfury Weapon for extra attacks. Stormstrike and Lava Lash are the strikes, and Maelstrom Weapon turns melee swings into instant Lightning Bolts and Chain Heals. Feral Spirit calls two wolves as a cooldown.', 'enhancement shaman,enh shaman,stormstrike,lava lash,feral spirit,maelstrom weapon,windfury weapon,melee shaman', 'spec,shaman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_restoration_shaman', 'Restoration Shaman', 'Restoration is the shaman healing tree and the strongest party healer of this expansion. Chain Heal bounces between injured group members, Riptide is the instant that strengthens the next Chain Heal, and Earth Shield sits on the tank soaking hits. Mana Tide Totem gives the group its mana back.', 'restoration shaman,resto shaman,chain heal,riptide,earth shield,mana tide totem,earthliving weapon,shaman healer', 'spec,shaman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_arcane_mage', 'Arcane Mage', 'Arcane is the burst and mana-management tree. Arcane Blast hits harder with every stack and costs more mana for it, so the spec is a constant decision about when to dump the stack with Arcane Barrage or Arcane Missiles. Presence of Mind and Arcane Power are the burst cooldowns. It has the highest ceiling and the worst mana problems.', 'arcane mage,arcane blast,arcane barrage,arcane missiles,arcane power,presence of mind,missile barrage', 'spec,mage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_fire_mage', 'Fire Mage', 'Fire is built on critical strikes feeding themselves: Hot Streak turns two crits in a row into an instant Pyroblast. Fireball and Scorch are the fillers, Living Bomb ticks and then explodes, and Combustion is the burst cooldown. Without critical strike rating the whole tree stalls.', 'fire mage,hot streak,living bomb,pyroblast,combustion,fireball', 'spec,mage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_frost_mage', 'Frost Mage', 'Frost is the survivable mage tree and the usual choice for levelling alone. Frostbolt slows whatever it hits and Frost Nova roots, while Shatter turns frozen targets into guaranteed critical strikes for Ice Lance. Summon Water Elemental gives Frost a pet, and Deep Freeze is a stun that instead deals heavy damage to anything immune to stuns.', 'frost mage,frostbolt,ice lance,deep freeze,icy veins,water elemental,fingers of frost,frost nova', 'spec,mage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_affliction_warlock', 'Affliction Warlock', 'Affliction is the damage-over-time tree. Corruption, Curse of Agony and Unstable Affliction tick on the target while Haunt raises all of that damage and returns the healing to the warlock. Drain Soul hits far harder on a target about to die. Strong on one target and unforgiving if the timers are left to lapse.', 'affliction warlock,affli warlock,unstable affliction,haunt,curse of agony,drain soul,dot warlock,affli lock,aff lock', 'spec,warlock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_demonology_warlock', 'Demonology Warlock', 'Demonology is the pet tree. The Felguard is its own summon, Demonic Empowerment buffs whatever demon is out, and Soul Link splits damage between warlock and pet. Metamorphosis is the deep talent: the warlock becomes a demon with its own abilities. Demonic Pact hands the raid spell power off the pet''s critical strikes.', 'demonology warlock,demo warlock,felguard,metamorphosis,demonic empowerment,soul link,demonic pact,pet warlock,demo lock', 'spec,warlock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_destruction_warlock', 'Destruction Warlock', 'Destruction is the direct damage tree, built on Immolate and Incinerate with Conflagrate consuming the Immolate for a burst. Chaos Bolt is the deep talent: it cannot be resisted and ignores absorption shields. Backdraft speeds up casting afterwards and Shadowburn is the finisher.', 'destruction warlock,destro warlock,chaos bolt,conflagrate,incinerate,immolate,shadowburn,backdraft,destro lock', 'spec,warlock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_balance_druid', 'Balance Druid', 'Balance is the caster druid tree, played in Moonkin Form, which is why everyone calls it boomkin. Eclipse alternates a bonus between Starfire and Wrath, so the spec swings between arcane and nature damage. Moonfire and Insect Swarm keep damage ticking, Starfall rains on everything nearby, and Typhoon knocks targets back.', 'balance druid,boomkin,moonkin,moonkin form,starfall,eclipse,starfire,insect swarm,typhoon,caster druid', 'spec,druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_feral_druid', 'Feral Druid', 'Feral covers both melee roles: cat form for damage, dire bear form for tanking. As a cat it builds combo points with Rake and Shred and spends them on Rip and Savage Roar; as a bear it holds threat with Maul and Mangle. Mangle is the tree''s shared signature and Berserk is its cooldown in either form.', 'feral druid,cat form,bear form,dire bear form,mangle,shred,savage roar,rake,kitty druid,feral tank', 'spec,druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('spec_restoration_druid', 'Restoration Druid', 'Restoration heals with rolling periodic spells rather than large casts: Rejuvenation and Lifebloom tick away while Nourish and Regrowth cover the gaps. Wild Growth is the tree''s raid heal and Swiftmend consumes a Rejuvenation or Regrowth for an instant one. Tree of Life is the form the spec heals in.', 'restoration druid,resto druid,tree of life,wild growth,swiftmend,rejuvenation,lifebloom,nourish,druid healer', 'spec,druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_hallows_end', 'Hallow''s End', 'Hallow''s End runs each year from October 18 to October 31, decorating capital cities with pumpkins and letting players trick-or-treat at candy buckets in every inn for random treats, including a small chance at the flying Magic Broom mount. Its centerpiece is a fight against the Headless Horseman, summoned in Scarlet Monastery''s graveyard; since patch 3.3.3 he can be queued for directly through the Dungeon Finder instead of forming a group by hand. Players can also throw Weighted Jack-o''-Lanterns and pick up a costume wand that turns them into a ghost, ninja, pirate, skeleton, bat, wisp, or leper gnome for the duration of the holiday.', 'hallow''s end,headless horseman,magic broom,trick or treat,candy bucket,scarlet monastery', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_winter_veil', 'Feast of Winter Veil', 'The Feast of Winter Veil is WoW''s Christmas-themed holiday, running from December 15 through January 2. Players collect a daily gift from under the tree beside Greatfather Winter in Ironforge or Orgrimmar, buy toys and treats from the traveling Smokywood Pastures vendor, and can start snowball fights or use a Handful of Snowflakes to turn friends into reindeer. There is no dedicated Winter Veil mount, but achievements like Merrymaker (completing every holiday task) award a title, and the classic ''Metzen the Reindeer'' summon is a well-known joke item tied to the season.', 'feast of winter veil,winter veil,greatfather winter,smokywood pastures,reindeer,snowball', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_brewfest', 'Brewfest', 'Brewfest runs from September 20 to October 4 at fairgrounds outside Ironforge and Orgrimmar, where players ram-race, sample brews from the Brewfest quartermaster for tokens, and fight the drunken boss Coren Direbrew inside Blackrock Depths (also queueable through the Dungeon Finder). Defeating Direbrew drops a loot bag with a chance at the Great Brewfest Kodo or the Swift Brewfest Ram mount, making his fight the event''s main draw for collectors. Brewfest carries no reputation of its own; the daily quests and the ram race pay Brewfest Prize Tokens, spent with a Token Redeemer on holiday-only gear, steins, and trinkets.', 'brewfest,coren direbrew,brewfest kodo,brewfest ram,ram racing,blackrock depths', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_midsummer_fire_festival', 'Midsummer Fire Festival', 'The Midsummer Fire Festival burns from June 21 to July 4 around bonfires placed in most major cities and zones. Players tend their own faction''s flame, try to douse the rival faction''s fire and relight their own from it, and dance around the Ribbon Pole for a festive buff; visiting every bonfire and completing the fire-themed dailies works toward the Fire Festival meta-achievement and title. Rewards are mostly cosmetic -- torch-tossing toys and a Brazier of Dancing Flames trinket -- with no dedicated mount tied to the holiday.', 'midsummer fire festival,bonfire,ribbon pole,torch,brazier of dancing flames', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_lunar_festival', 'Lunar Festival', 'Lunar Festival runs from February 1 to February 14 and centers on visiting Elders scattered across nearly every zone on both continents, each granting the Elders'' Blessing buff and a bit of Lunar Festival lore. Players also toss coins into the fountain at Moonglade for a random small reward, and can take on Omen, an enormous spectral beast that spawns as a group-killable target in Moonglade for the duration of the event. Collecting blessings from enough Elders unlocks the elder title and a fireworks-launching trinket.', 'lunar festival,elders,elders'' blessing,moonglade,omen,coin toss', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_love_is_in_the_air', 'Love is in the Air', 'Love is in the Air runs from February 10 to February 23; Wrath of the Lich King''s patch 3.3 expanded it from a minor vanilla holiday into a full event centered on a farcical boss fight against Apothecary Hummel and his gang of thugs in each capital city. Defeating Hummel drops a loot bag with a small chance at the Big Love Rocket, one of the game''s most sought-after rare mounts. Players also collect Lovely Charms from monsters everywhere to trade for perfume, cologne, and the companion pet Peddlefeet, and can propose to friends with a Silver Bell or invite them to disco-dance atop a caged Love Fool.', 'love is in the air,apothecary hummel,big love rocket,lovely charms,peddlefeet', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_childrens_week', 'Children''s Week', 'Children''s Week runs from April 30 to May 6. Players adopt a war orphan from the Orphan Matron in their faction''s capital and escort it on a tour of iconic locations, including a Northrend leg added for Wrath of the Lich King that has players take their orphan through Icecrown or Borean Tundra. It is also when the School of Hard Knocks achievement is available, which sends players into the battlegrounds with the orphan following them to capture a flag, assault a tower, and the like -- a notoriously unpopular week for battleground regulars. Completing the full questline awards a faction-specific orphan companion pet.', 'children''s week,orphan,orphan matron,school of hard knocks,companion pet', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_pilgrims_bounty', 'Pilgrim''s Bounty', 'Pilgrim''s Bounty is WoW''s Thanksgiving-themed holiday, added with Wrath of the Lich King and running from November 21 to November 27 at a feast table set up outside every major city. Players cook and serve dishes like Cranberry Chutney, Pumpkin Pie, and Slow-Roasted Turkey to seated guests of both factions for reputation and Pilgrim''s Bounty Buckets, and can earn the Pilgrim''s Paunch food-coma buff for overeating. The Turkinator achievement, earned by killing wild turkeys that spawn worldwide during the event, rounds out the holiday''s meta-achievement.', 'pilgrim''s bounty,turkinator,pilgrim''s paunch,cranberry chutney,thanksgiving', 'event,holiday,seasonal,wotlk');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_elwynn_forest', 'Elwynn Forest', 'Elwynn Forest is the level 1-10 starting zone for humans, just outside Stormwind City. New characters begin at Northshire Abbey, then move to Goldshire, the main town, with its Lion''s Pride Inn. Common enemies are wolves, kobolds in the mines and Defias bandits.', 'elwynn,elwynn forest,goldshire,northshire,northshire abbey,northshire valley,lions pride inn', 'zone,starting_area,human,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_durotar', 'Durotar', 'Durotar is the level 1-10 starting zone for orcs and trolls, outside Orgrimmar. New characters begin in the Valley of Trials, then quest from Razor Hill and Sen''jin Village near the Echo Isles. Common enemies are boars, scorpids, Razormane quilboar and Burning Blade cultists.', 'durotar,razor hill,valley of trials,sen jin village,echo isles', 'zone,starting_area,horde,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_teldrassil', 'Teldrassil', 'Teldrassil is the level 1-10 starting zone for night elves, on the giant tree that holds Darnassus. New characters begin in Shadowglen beneath Aldrassil, then quest from Dolanaar. Common enemies are nightsabers, spiders and corrupted furbolgs, and the boat at Rut''theran Village goes to Darkshore.', 'teldrassil,shadowglen,dolanaar,aldrassil', 'zone,starting_area,alliance,night_elf,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_mulgore', 'Mulgore', 'Mulgore is the level 1-10 starting zone for tauren, below Thunder Bluff. New characters begin at Camp Narache on Red Cloud Mesa, then quest from Bloodhoof Village. Common enemies are plainstriders, prairie wolves, Palemane gnolls, Bristleback quilboar and Venture Company miners.', 'mulgore,bloodhoof village,camp narache,red cloud mesa', 'zone,starting_area,horde,tauren,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dun_morogh', 'Dun Morogh', 'Dun Morogh is the level 1-10 starting zone for dwarves and gnomes, around Ironforge. New characters begin at Anvilmar in Coldridge Valley, then quest from Kharanos and its Thunderbrew Distillery inn. Common enemies are Rockjaw troggs, Frostmane trolls, boars and wolves.', 'dun morogh,kharanos,coldridge valley,anvilmar,thunderbrew distillery', 'zone,starting_area,alliance,dwarf,gnome,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_tirisfal_glades', 'Tirisfal Glades', 'Tirisfal Glades is the level 1-10 starting zone for the undead, above the Undercity. New characters rise in Deathknell, then quest from the town of Brill. Common enemies are mindless zombies, Scourge, and the Scarlet Crusade, whose monastery sits in the zone''s north.', 'tirisfal,tirisfal glades,deathknell,brill', 'zone,starting_area,horde,undead,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_azuremyst_isle', 'Azuremyst Isle', 'Azuremyst Isle is the level 1-10 starting zone for draenei, beside the Exodar. New characters begin in Ammen Vale by the Crash Site, then quest from Azure Watch. Common enemies are owlkin, Bristlelimb furbolgs and crash-mutated wildlife; the next zone is Bloodmyst Isle.', 'azuremyst,azuremyst isle,ammen vale,azure watch,crash site', 'zone,starting_area,alliance,draenei,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_eversong_woods', 'Eversong Woods', 'Eversong Woods is the level 1-10 starting zone for blood elves, outside Silvermoon City. New characters begin on Sunstrider Isle, then quest from Falconwing Square and Fairbreeze Village. Common enemies are mana wyrms, arcane wraiths and Wretched elves; the next zone is the Ghostlands.', 'eversong,eversong woods,sunstrider isle,falconwing square,fairbreeze village', 'zone,starting_area,horde,blood_elf,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_borean_tundra', 'Borean Tundra', 'Borean Tundra is a level 68-72 Northrend zone. Alliance arrive by boat at Valiance Keep and Horde by zeppelin at Warsong Hold. Its quests fight the Scourge, nerubians and the blue dragonflight, whose Nexus stands on Coldarra in the zone''s west.', 'borean,borean tundra,valiance keep,warsong hold,coldarra,riplash,amber ledge', 'zone,northrend,leveling,wrath,contested');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_howling_fjord', 'Howling Fjord', 'Howling Fjord is a level 68-72 Northrend zone. Alliance arrive by boat at Valgarde and Horde by zeppelin at Vengeance Landing. Its quests fight the vrykul, whose stronghold Utgarde Keep is the zone''s dungeon, and the Forsaken''s plague works at New Agamand.', 'howling fjord,valgarde,vengeance landing,camp winterhoof,new agamand,westguard keep', 'zone,northrend,leveling,wrath,contested');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_westfall', 'Westfall', 'Westfall is a level 10 to 20 Alliance zone of failing farmland west of Elwynn Forest. The Defias Brotherhood and their harvest golems have overrun the farms, and the People''s Militia works out of Sentinel Hill. It holds the entrance to the Deadmines and the long-running Defias questline, and Alliance players usually quest here right after Elwynn.', 'westfall,sentinel hill,defias brotherhood,harvest golem,peoples militia,deadmines entrance,moonbrook', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_loch_modan', 'Loch Modan', 'Loch Modan is a level 10 to 20 dwarven zone east of Dun Morogh, built around a great lake and the Stonewrought Dam. Thelsamar is the quest hub. Troggs, kobolds, and the Dark Iron dwarves press in from the hills, and the Explorers'' League digs at the Farstrider Lodge and Ironband''s excavation site.', 'loch modan,thelsamar,stonewrought dam,the loch,ironbands excavation,farstrider lodge', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_silverpine_forest', 'Silverpine Forest', 'Silverpine Forest is a level 10 to 20 Horde zone south of Tirisfal Glades, dark and worgen-haunted. The Sepulcher is the Forsaken quest hub, and Shadowfang Keep sits at its southern edge above Pyrewood Village. Dalaran''s old magical dome once stood here, and the Dalaran mages still hold ruins in the east.', 'silverpine forest,silverpine,the sepulcher,shadowfang keep entrance,pyrewood village,ambermill', 'zone,horde,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ghostlands', 'Ghostlands', 'Ghostlands is a level 10 to 20 blood elf zone south of Eversong Woods, scarred by the Scourge''s march on Quel''Thalas. Tranquillien is the quest hub, and the Dead Scar cuts through the middle of the zone. It leads on to Zul''Aman and connects Silvermoon''s territory to the rest of the Eastern Kingdoms.', 'ghostlands,tranquillien,dead scar,quelthalas,zulaman entrance', 'zone,horde,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_redridge_mountains', 'Redridge Mountains', 'Redridge Mountains is a level 15 to 25 Alliance zone east of Elwynn Forest, centered on Lakeshire and its broken bridge. Blackrock orcs push down from Render''s Camp in the north and gnolls hold the southern hills. It borders Duskwood to the south and the Burning Steppes far to the north.', 'redridge mountains,redridge,lakeshire,blackrock orcs,renders camp,lake everstill,stonewatch', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_duskwood', 'Duskwood', 'Duskwood is a level 18 to 30 zone of permanent night south of Elwynn Forest, with Darkshire as its quest hub. Worgen, undead, and spiders roam the roads, and the Night Watch patrols nervously. It holds the Stalvan Mistmantle and Mor''Ladim questlines, Raven Hill Cemetery, and the entrance to Deadwind Pass in the east.', 'duskwood,darkshire,night watch,raven hill,raven hill cemetery,morladim,stalvan mistmantle,twilight grove', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hillsbrad_foothills', 'Hillsbrad Foothills', 'Hillsbrad Foothills is a level 20 to 30 contested zone below Alterac, famous for open world PvP between Tarren Mill and Southshore. The Forsaken hold Tarren Hill in the north and the Alliance hold Southshore on the coast. Durnholde Keep and the Syndicate occupy the eastern hills.', 'hillsbrad foothills,hillsbrad,tarren mill,southshore,durnholde keep,azurelode mine', 'zone,contested,eastern_kingdoms,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_wetlands', 'Wetlands', 'Wetlands is a level 20 to 30 Alliance-leaning zone of marsh and rain north of Dun Morogh, with Menethil Harbor as its port and quest hub. Raptors, murlocs, and crocolisks make the roads dangerous for the level range. Boats from Menethil run to Theramore in Kalimdor and to Howling Fjord in Northrend.', 'wetlands,menethil harbor,dun modr,grim batol,boat to theramore', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_arathi_highlands', 'Arathi Highlands', 'Arathi Highlands is a level 30 to 40 contested zone of open grassland, with Refuge Pointe for the Alliance and Hammerfall for the Horde. Stromgarde Keep lies ruined in the southwest, contested by the Syndicate and Boulderfist ogres. The Arathi Basin battleground takes its name and setting from this zone.', 'arathi highlands,arathi,refuge pointe,hammerfall,stromgarde keep,boulderfist ogres', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_alterac_mountains', 'Alterac Mountains', 'Alterac Mountains is a level 30 to 40 contested snow zone between Hillsbrad and the Hinterlands. The ruins of Alterac city are held by the Syndicate, and yetis and ogres fill the valleys. It is thinly quested compared to its neighbours, and its main draw is the entrance to Alterac Valley in the north.', 'alterac mountains,alterac,ruins of alterac,alterac valley entrance,dalaran crater', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_stranglethorn_vale', 'Stranglethorn Vale', 'Stranglethorn Vale is a level 30 to 45 contested jungle at the south end of the Eastern Kingdoms, notorious for world PvP along its single road. Booty Bay in the far south is a neutral goblin port with an auction house. Grom''gol Base Camp serves the Horde, Rebel Camp the Alliance, and Zul''Gurub sits in the eastern jungle.', 'stranglethorn vale,stranglethorn,booty bay,gromgol base camp,rebel camp,nesingwary,zulgurub entrance,bloodsail buccaneers,stv', 'zone,contested,eastern_kingdoms,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_badlands', 'Badlands', 'Badlands is a level 35 to 45 contested canyon zone south of Loch Modan, all red rock and dust. Kargath serves the Horde and the Dwarven District of Thelsamar supplies the Alliance side from the north. Its main feature is the entrance to Uldaman, and black dragonkin and Dark Iron dwarves contest the excavation sites.', 'badlands,kargath,uldaman entrance,angor fortress,lethlor ravine', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_swamp_of_sorrows', 'Swamp of Sorrows', 'Swamp of Sorrows is a level 35 to 45 contested marsh east of Duskwood, sunk in permanent fog and rain. Stonard is the Horde outpost, and the Alliance has no real foothold. The Sunken Temple lies beneath the Temple of Atal''Hakkar in the north of the zone, and the Dark Portal sits just east in the Blasted Lands.', 'swamp of sorrows,stonard,sunken temple,temple of atalhakkar,misty valley,pool of tears', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hinterlands', 'The Hinterlands', 'The Hinterlands is a level 40 to 50 contested forest north of the Plaguelands, home to the Wildhammer dwarves at Aerie Peak and the Revantusk trolls on the eastern coast. Vilebranch and Witherbark forest trolls hold most of the zone. Aerie Peak is also the entrance to Seradane and a common Alliance flight point.', 'the hinterlands,hinterlands,aerie peak,wildhammer dwarves,revantusk village,vilebranch trolls,witherbark,jintha alor', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_searing_gorge', 'Searing Gorge', 'Searing Gorge is a level 43 to 50 contested zone of ash and open flame between the Badlands and the Burning Steppes. The Thorium Brotherhood works out of Thorium Point, and the Dark Iron dwarves hold the Slag Pit and Blackrock. It is the surface approach to Blackrock Depths and a prime mining zone for thorium.', 'searing gorge,thorium point,thorium brotherhood,the slag pit,blackrock depths approach', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_blasted_lands', 'Blasted Lands', 'Blasted Lands is a level 45 to 55 contested wasteland at the southern tip of the Eastern Kingdoms, and it holds the Dark Portal to Outland. Nethergarde Keep serves the Alliance and Dreadmaul Hold the Horde. Players crossing to Outland at level 58 pass through here, so the zone stays busy well past its own level range.', 'blasted lands,dark portal,nethergarde keep,dreadmaul hold,outland entrance,portal to outland,rise of the defiler', 'zone,contested,eastern_kingdoms,leveling,outland_gateway');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_burning_steppes', 'Burning Steppes', 'Burning Steppes is a level 50 to 58 contested zone of lava and black rock, north of Redridge and below Blackrock Mountain. Morgan''s Vigil holds the Alliance camp and Flame Crest the Horde. The zone is the front door to Blackrock Spire and Molten Core, and Dark Iron dwarves and black dragonkin patrol the roads.', 'burning steppes,morgans vigil,flame crest,blackrock mountain,blackrock spire entrance,molten core entrance', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_western_plaguelands', 'Western Plaguelands', 'Western Plaguelands is a level 51 to 58 contested zone of Scourge-blighted farmland, with Chillwind Camp for the Alliance and the Bulwark on the Horde approach. Andorhal lies ruined at its center and Hearthglen in the north is held by the Scarlet Crusade. Scholomance sits on Caer Darrow in the southeast.', 'western plaguelands,chillwind camp,andorhal,hearthglen,caer darrow,scholomance entrance,the bulwark,wpl', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_eastern_plaguelands', 'Eastern Plaguelands', 'Eastern Plaguelands is a level 53 to 60 contested zone and the darkest ground in the Eastern Kingdoms, with the Argent Dawn holding Light''s Hope Chapel against the Scourge. Stratholme lies in the northwest behind its gates, and Naxxramas floated above the zone before it moved to Northrend. The plaguewood and Blackwood are thick with undead.', 'eastern plaguelands,lights hope chapel,stratholme entrance,plaguewood,corins crossing,epl', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_deadwind_pass', 'Deadwind Pass', 'Deadwind Pass is a level 55 to 60 contested corridor between Duskwood and the Swamp of Sorrows, and it has almost no quests of its own. Its reason to exist is Karazhan, Medivh''s tower, which looms over the southern end of the pass and is the entry raid of the Burning Crusade.', 'deadwind pass,karazhan,medivh,medivhs tower,deadwind', 'zone,contested,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_isle_of_queldanas', 'Isle of Quel''Danas', 'Isle of Quel''Danas is a level 70 daily quest island north of Quel''Thalas, added at the end of the Burning Crusade. Both factions share the Shattered Sun Offensive base there, and the zone unlocks progressively through server-wide phases. It holds Magisters'' Terrace and the Sunwell Plateau raid.', 'isle of queldanas,queldanas,shattered sun offensive,sunwell plateau,magisters terrace,sunwell', 'zone,neutral,eastern_kingdoms,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_bloodmyst_isle', 'Bloodmyst Isle', 'Bloodmyst Isle is a level 10 to 20 draenei zone north of Azuremyst Isle, stained red by the crash of the Exodar. Blood Watch is the quest hub. It follows straight on from the draenei starting experience and ends around the level where players leave for Darkshore or Darnassus.', 'bloodmyst isle,bloodmyst,blood watch,exodar crash,vector coil,wrathscale naga', 'zone,alliance,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_darkshore', 'Darkshore', 'Darkshore is a level 10 to 20 night elf zone along the western coast of Kalimdor, below Teldrassil. Auberdine is the port and quest hub, with boats to Menethil Harbor, Rut''theran Village, and the Exodar. Ruins, murlocs, and the Twilight''s Hammer occupy the coast, and Blackfathom Deeps lies at the southern end.', 'darkshore,auberdine,blackfathom deeps entrance', 'zone,alliance,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_the_barrens', 'The Barrens', 'The Barrens is the great level 10 to 25 Horde zone across central Kalimdor, split by the Gold Road and remembered for its chat channel. Crossroads is the main quest hub, with Camp Taurajo south and Ratchet on the eastern coast as a neutral goblin port. Wailing Caverns sits in the Wailing Caverns oasis in the north.', 'the barrens,barrens,crossroads,camp taurajo,ratchet,wailing caverns entrance,gold road,barrens chat,razorfen', 'zone,horde,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_stonetalon_mountains', 'Stonetalon Mountains', 'Stonetalon Mountains is a level 15 to 27 contested zone of pine ridges northwest of the Barrens. Sun Rock Retreat serves the Horde and Stonetalon Peak the Alliance. Venture Company goblins are logging the forest, which drives most of the zone''s quests, and the Charred Vale lies burnt in the south.', 'stonetalon mountains,stonetalon,sun rock retreat,stonetalon peak,charred vale,windshear crag', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ashenvale', 'Ashenvale', 'Ashenvale is a level 18 to 30 contested night elf forest north of the Barrens, heavily fought over by Warsong loggers and the Sentinels. Astranaar is the Alliance hub and Splintertree Post the Horde''s. Blackfathom Deeps lies on its western coast and the Warsong Lumber Camp drives the faction conflict here.', 'ashenvale,astranaar,splintertree post,warsong lumber camp,silverwing', 'zone,contested,kalimdor,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_thousand_needles', 'Thousand Needles', 'Thousand Needles is a level 25 to 35 contested zone of towering mesas and dry canyons south of the Barrens. Freewind Post sits atop a mesa as the Horde hub. The Shimmering Flats in the southeast host the goblin racetrack, and centaur and Grimtotem tauren hold the canyon floor.', 'thousand needles,freewind post,shimmering flats,mirage raceway,goblin racetrack,razorfen downs', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_desolace', 'Desolace', 'Desolace is a level 30 to 40 contested wasteland on Kalimdor''s western coast, grey and thinly populated. Nijel''s Point serves the Alliance and Shadowprey Village the Horde. Centaur clans war across the middle of the zone and Maraudon''s entrance lies in the Valley of Spears in the south.', 'desolace,nijels point,shadowprey village,maraudon entrance,valley of spears,kodo graveyard', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dustwallow_marsh', 'Dustwallow Marsh', 'Dustwallow Marsh is a level 35 to 45 contested swamp on Kalimdor''s eastern coast, holding the Alliance city of Theramore Isle under Jaina Proudmoore and the Horde camp at Brackenwall Village. Onyxia''s Lair sits in the wyrmbog to the south, and Mudsprocket in the southwest was added as a later goblin hub.', 'dustwallow marsh,theramore isle,theramore,jaina proudmoore,brackenwall village,onyxias lair entrance,the wyrmbog,mudsprocket', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_feralas', 'Feralas', 'Feralas is a level 40 to 50 contested jungle in southwestern Kalimdor, thick with yeti, ogres, and gorillas. Feathermoon Stronghold serves the Alliance from an island in the west and Camp Mojache the Horde. Dire Maul lies in the ruins of Eldre''Thalas at the center of the zone.', 'feralas,feathermoon stronghold,camp mojache,dire maul entrance,eldrethalas,gordunni ogres', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_tanaris', 'Tanaris', 'Tanaris is a level 40 to 50 contested desert in southern Kalimdor, with the neutral goblin port of Gadgetzan as its hub and an auction house. The Caverns of Time open in the Tanaris cliffs, and Zul''Farrak lies in the northwest. Silithid, pirates at Lost Rigger Cove, and basilisks fill the sands.', 'tanaris,gadgetzan,caverns of time,zulfarrak entrance,lost rigger cove,steamwheedle port,noggenfogger', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_azshara', 'Azshara', 'Azshara is a level 45 to 55 contested zone in northeastern Kalimdor, overgrown and lightly quested before Cataclysm reworked it. Valormok is the Horde camp and Talrendis Point the Alliance''s. Naga hold the ruins along the coast and the Timbermaw and blue dragonflight both have interests in the north.', 'azshara,valormok,talrendis point,ruins of eldarath,bay of storms,legash encampment', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_felwood', 'Felwood', 'Felwood is a level 48 to 55 contested zone north of Ashenvale, corrupted by demonic taint into sickly green forest. Emerald Sanctuary and Whisperwind Grove hold the Cenarion Circle''s efforts to cleanse it. Timbermaw Hold in the north is a neutral furbolg faction worth grinding for the shortcut it opens to Winterspring and Moonglade.', 'felwood,emerald sanctuary,whisperwind grove,timbermaw hold,irontree woods', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ungoro_crater', 'Un''Goro Crater', 'Un''Goro Crater is a level 48 to 55 contested prehistoric basin south of Silithus, full of devilsaurs, raptors, and elementals. Marshal''s Refuge in the middle is the neutral hub, and the crater is one of the best places in the old world for herbs, ore, and power crystals. A devilsaur will kill an unprepared player of its level range.', 'ungoro crater,ungoro,marshals refuge,devilsaur,power crystals,fire plume ridge,golakka hot springs', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_silithus', 'Silithus', 'Silithus is a level 55 to 60 contested desert in southwestern Kalimdor, crawling with silithid and the Twilight''s Hammer cult. Cenarion Hold is the quest hub and the Cenarion Circle reputation grind runs from there. The gates of Ahn''Qiraj stand at the zone''s southern edge, opening onto the two Ahn''Qiraj raids.', 'silithus,cenarion hold,ahnqiraj gates,scarab lord', 'zone,contested,kalimdor,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_winterspring', 'Winterspring', 'Winterspring is a level 55 to 60 contested snow zone in northeastern Kalimdor, with the neutral goblin town of Everlook as its hub. Frostsabers, yeti, and chimaera roam the drifts. It holds the Frostsaber mount grind for night elves and heavy thorium and arcane crystal mining in the Mazthoril caves.', 'winterspring,everlook,frostsaber,mazthoril,starfall village', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_moonglade', 'Moonglade', 'Moonglade is a small neutral sanctuary valley in northern Kalimdor, sacred to druids and reachable by the Teleport: Moonglade spell any druid learns at level 14. Nighthaven is its only settlement, home to the Cenarion Circle and Remulos. It has no hostile mobs and no level range: druids come here for class quests and everyone else for the Lunar Festival.', 'moonglade,nighthaven,druid sanctuary,teleport moonglade,keeper remulos,timbermaw tunnel', 'zone,neutral,kalimdor,sanctuary,druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hellfire_peninsula', 'Hellfire Peninsula', 'Hellfire Peninsula is the level 58 to 63 entry zone of Outland, the red broken land on the far side of the Dark Portal. Honor Hold serves the Alliance and Thrallmar the Horde. Hellfire Citadel sits at the center with Ramparts, Blood Furnace, Shattered Halls, and Magtheridon''s Lair, and the zone has a heavy world PvP presence around its towers.', 'hellfire peninsula,hellfire,honor hold,thrallmar,dark portal,hellfire citadel,ramparts,blood furnace,magtheridon', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_zangarmarsh', 'Zangarmarsh', 'Zangarmarsh is a level 60 to 64 Outland zone of giant mushrooms and standing water, home to the Cenarion Expedition at Cenarion Refuge and the sporeggar mushroom folk. Telredor serves the Alliance and Zabra''jin the Horde. The Coilfang Reservoir instances, including Slave Pens, Underbog, Steamvault, and Serpentshrine Cavern, all open here.', 'zangarmarsh,cenarion expedition,sporeggar,telredor,zabrajin,coilfang reservoir,slave pens,underbog,steamvault,serpentshrine cavern', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_terokkar_forest', 'Terokkar Forest', 'Terokkar Forest is a level 62 to 65 Outland zone of tall bone-white trees, and it surrounds Shattrath City. Allerian Stronghold serves the Alliance and Stonebreaker Hold the Horde. Auchindoun sits in the Bone Wastes at its center with four wings, and the Skettis arakkoa hold the southeast.', 'terokkar forest,terokkar,shattrath,allerian stronghold,stonebreaker hold,auchindoun,bone wastes,skettis,lower city', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_nagrand', 'Nagrand', 'Nagrand is a level 64 to 67 Outland zone of green plains and floating islands, widely considered the best-looking zone of the Burning Crusade. Telaar serves the Alliance and Garadar the Horde, and the Mag''har orcs quest chain runs from Garadar. Halaa in the center is a world PvP objective, and the Ring of Blood is a well-known group quest gauntlet.', 'nagrand,telaar,garadar,maghar orcs,halaa,ring of blood,throne of the elements', 'zone,contested,outland,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_blades_edge_mountains', 'Blade''s Edge Mountains', 'Blade''s Edge Mountains is a level 65 to 68 Outland zone of jagged spires, ogre holds, and dragon bones driven into the rock. Sylvanaar serves the Alliance and Thunderlord Stronghold the Horde. Gruul''s Lair opens in the northwest and the Ogri''la plateau in the east unlocks daily quests at level 70.', 'blades edge mountains,blades edge,sylvanaar,thunderlord stronghold,gruuls lair,ogrila,bladespire,skyguard', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_netherstorm', 'Netherstorm', 'Netherstorm is a level 67 to 70 Outland zone of shattered floating landmass and arcane storms in the northeast. Area 52 is the neutral goblin hub, and the Consortium and Kirin Tor both operate here. Tempest Keep, with the Arcatraz, Botanica, Mechanar, and Eye, sits at the zone''s western edge as Kael''thas Sunstrider''s stronghold.', 'netherstorm,area 52,tempest keep,arcatraz,botanica,mechanar,the eye,kaelthas sunstrider,manaforge', 'zone,contested,outland,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_shadowmoon_valley', 'Shadowmoon Valley', 'Shadowmoon Valley is a level 67 to 70 Outland zone of black rock and lava in the southeast, and the last leveling zone of the Burning Crusade. Wildhammer Stronghold serves the Alliance and Shadowmoon Village the Horde. The Black Temple, Illidan Stormrage''s fortress, dominates the middle of the zone, and the Netherwing ledge offers drake mount dailies at level 70.', 'shadowmoon valley,black temple,illidan stormrage,wildhammer stronghold,shadowmoon village,netherwing ledge,netherwing drake,altar of sha,coilskar', 'zone,contested,outland,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dragonblight', 'Dragonblight', 'Dragonblight is a level 71 to 74 Northrend zone at the center of the continent, where dragons come to die. Wintergarde Keep serves the Alliance and Agmar''s Hammer the Horde, with the neutral Wyrmrest Temple rising at the middle. Azjol-Nerub and the Old Kingdom open in the north, Naxxramas floats in the northeast, and the Wrathgate questline plays out here.', 'dragonblight,wyrmrest temple,wintergarde keep,agmars hammer,azjolnerub,old kingdom,naxxramas entrance,wrathgate,dragon graveyard', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_grizzly_hills', 'Grizzly Hills', 'Grizzly Hills is a level 73 to 75 Northrend zone of dense pine forest and logging camps, known for its music. Amberpine Lodge serves the Alliance and Conquest Hold the Horde. The Drakkari trolls, the Venture Company, and the worgen of Grizzlemaw drive most of the questing, and Drak''Tharon Keep sits on the border with Zul''Drak.', 'grizzly hills,amberpine lodge,conquest hold,grizzlemaw,draktharon keep', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_zuldrak', 'Zul''Drak', 'Zul''Drak is a level 74 to 76 Northrend zone, the ice troll homeland, where the Drakkari are killing their own gods for power. The Argent Crusade holds Light''s Breach and the Ebon Blade operates at Ebon Watch. Gundrak sits at the northern end of the zone, and the Amphitheater of Anguish runs a well-known gauntlet of group quests.', 'zuldrak,drakkari,gundrak,lights breach,ebon watch,amphitheater of anguish', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_sholazar_basin', 'Sholazar Basin', 'Sholazar Basin is a level 76 to 78 Northrend zone, a tropical valley sealed inside the ice and untouched by the Lich King. Nesingwary''s camp runs the hunting quests, and the Oracles and the Frenzyheart Tribe are opposed reputations: siding with one locks out the other, and each offers its own dailies and pets.', 'sholazar basin,sholazar,the oracles,frenzyheart tribe,nesingwary', 'zone,neutral,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_storm_peaks', 'The Storm Peaks', 'The Storm Peaks is a level 76 to 80 Northrend zone of high mountains and titan architecture in the north, home to the Sons of Hodir. K3 is the goblin hub and Dun Niffelem the Sons of Hodir''s. The Sons of Hodir reputation is the only source of shoulder enchants in Wrath, and Ulduar opens from the western side of the zone.', 'the storm peaks,storm peaks,sons of hodir,dun niffelem,k3,ulduar entrance,brunnhildar,shoulder enchants,hyldnir', 'zone,contested,northrend,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_icecrown', 'Icecrown', 'Icecrown is the level 77 to 80 Northrend zone below the Lich King''s fortress, and the last leveling zone of Wrath. The Argent Crusade, the Knights of the Ebon Blade, and the Alliance and Horde all hold camps here. The Argent Tournament grounds run mounted daily quests, and Icecrown Citadel with the Trial of the Crusader sits at the zone''s heart.', 'icecrown,icecrown citadel,lich king,argent tournament,knights of the ebon blade,trial of the crusader,shadow vault', 'zone,contested,northrend,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_crystalsong_forest', 'Crystalsong Forest', 'Crystalsong Forest is a level 77 to 80 Northrend zone of crystalline trees at the center of the continent, directly beneath the floating city of Dalaran. It has very few quests of its own and exists mostly as the approach to Dalaran and a passage between Dragonblight, Zul''Drak, and the Storm Peaks.', 'crystalsong forest,crystalsong,crystalline trees,windrunners overlook,sunreavers command', 'zone,contested,northrend');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_wintergrasp', 'Wintergrasp', 'Wintergrasp is a level 77 to 80 Northrend zone that works as an open world PvP battleground rather than a leveling zone. Alliance and Horde fight over the Wintergrasp Fortress on a timer using siege vehicles and destructible walls. Holding the fortress grants the winning faction access to the Vault of Archavon raid and a damage buff, and losing it locks that out until the next battle.', 'wintergrasp,wintergrasp fortress,vault of archavon,tenacity,pvp zone', 'zone,contested,northrend,pvp,endgame');
